    -- addon:data.affix_text.arcane_barrage_leaves_an_arcane_buffet_o:text
    ["Arcane Barrage leaves an Arcane Buffet on every enemy it hits: @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power as Arcane damage over 6 sec, stacking 3 times (Does not stack)"] = "Arkanbeschuss hinterlässt bei jedem getroffenen Feind einen Arkanpuffer: Arkanschaden in Höhe von @value@100%@value@ @range@[20%-100%]@range@ Eurer Zaubermacht über 6 Sek., bis zu 3-mal stapelbar (Nicht stapelbar)",
    -- addon:data.affix_text.arcane_blast_at_4_stacks_opens_a_chaotic:text
