    -- addon:data.affix_text.arcane_blast_at_4_stacks_reduces_the_rem:text
    ["Arcane Blast at 4 stacks reduces the remaining cooldown of Arcane Power by @value@3@value@ @range@[1-3]@range@ sec (Does not stack)"] = "Arkanschlag verringert bei 4 Stapeln die verbleibende Abklingzeit von Arkane Macht um @value@3@value@ @range@[1-3]@range@ Sek. (Nicht stapelbar)",
