    -- addon:skillTree.bought_for_good_the_ashes:text
    ["Bought for good: the ashes leave your pool on Apply, the node stays through prestige and applies to every character of your account."] = "Dauerhaft gekauft: Die Asche verlässt Euren Vorrat beim Übernehmen, der Knoten bleibt über das Prestige hinweg erhalten und gilt für jeden Charakter Eures Accounts.",
