    -- addon:data.affix_text.disengage_leaves_a_gust_behind_you_absor:text
    ["Disengage leaves a gust behind you: absorbs @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power for 6 sec, and enemies in the gust are knocked down for 1 sec (not bosses) (Does not stack)"] = "Rückzug hinterlässt hinter Euch eine Böe: Sie absorbiert 6 Sek. lang Schaden in Höhe von @value@150%@value@ @range@[30%-150%]@range@ Eurer Angriffskraft, und Feinde in der Böe werden 1 Sek. lang niedergeschlagen (keine Bosse) (Nicht stapelbar)",
    -- addon:data.affix_family.dissolution:text
    ["Dissolution"] = "Auflösung",
    -- addon:data.affix_text.divine_storm_consecrates_the_ground_unde:text
    ["Divine Storm consecrates the ground under every enemy it hits for 4 sec: @value@50%@value@ @range@[10%-50%]@range@ of your Attack Power as Holy damage every second (Does not stack)"] = "Göttlicher Sturm weiht 4 Sek. lang den Boden unter jedem getroffenen Feind: jede Sekunde Heiligschaden in Höhe von @value@50%@value@ @range@[10%-50%]@range@ Eurer Angriffskraft (Nicht stapelbar)",
    -- addon:data.affix_text.divine_storm_heals_you_as_well_as_the_al:text
    ["Divine Storm heals you, as well as the allies it heals, for an extra @value@30%@value@ @range@[10%-30%]@range@ of its damage (Does not stack)"] = "Göttlicher Sturm heilt Euch sowie die Verbündeten, die er heilt, zusätzlich um @value@30%@value@ @range@[10%-30%]@range@ seines Schadens (Nicht stapelbar)",
