    -- addon:data.petdesc.40634:text
    ["Domesticated elekks are trained as mounts by the draenei people. In the wild they are hunted for their ivory tusks."] = "Zahme Elekks werden vom Volk der Draenei als Reittiere abgerichtet. In freier Wildbahn werden sie wegen ihrer Elfenbeinstoßzähne gejagt.",
    -- addon:data.petdesc.13548:text
