    -- addon:data.affix_text.during_bladestorm_you_take_value_10_valu:text
    ["During Bladestorm you take @value@10%@value@ @range@[6%-30%]@range@ less damage, and each enemy you hit heals you for 1 % of your health (Does not stack)"] = "Während Klingensturm aktiv ist, erleidet Ihr @value@10%@value@ @range@[6%-30%]@range@ weniger Schaden, und jeder getroffene Feind heilt Euch um 1% Eurer Gesundheit (Nicht stapelbar)",
    -- addon:data.affix_text.during_bladestorm_you_take_value_14_valu:text
    ["During Bladestorm you take @value@14%@value@ @range@[6%-30%]@range@ less damage, and each enemy you hit heals you for 1 % of your health (Does not stack)"] = "Während Klingensturm aktiv ist, erleidet Ihr @value@14%@value@ @range@[6%-30%]@range@ weniger Schaden, und jeder getroffene Feind heilt Euch um 1% Eurer Gesundheit (Nicht stapelbar)",
    -- addon:data.affix_text.during_bladestorm_you_take_value_20_valu:text
    ["During Bladestorm you take @value@20%@value@ @range@[6%-30%]@range@ less damage, and each enemy you hit heals you for 1 % of your health (Does not stack)"] = "Während Klingensturm aktiv ist, erleidet Ihr @value@20%@value@ @range@[6%-30%]@range@ weniger Schaden, und jeder getroffene Feind heilt Euch um 1% Eurer Gesundheit (Nicht stapelbar)",
    -- addon:data.affix_text.during_bladestorm_you_take_value_30_valu:text
    ["During Bladestorm you take @value@30%@value@ @range@[6%-30%]@range@ less damage, and each enemy you hit heals you for 1 % of your health (Does not stack)"] = "Während Klingensturm aktiv ist, erleidet Ihr @value@30%@value@ @range@[6%-30%]@range@ weniger Schaden, und jeder getroffene Feind heilt Euch um 1% Eurer Gesundheit (Nicht stapelbar)",
    -- addon:data.affix_text.during_bladestorm_you_take_value_6_value:text
    ["During Bladestorm you take @value@6%@value@ @range@[6%-30%]@range@ less damage, and each enemy you hit heals you for 1 % of your health (Does not stack)"] = "Während Klingensturm aktiv ist, erleidet Ihr @value@6%@value@ @range@[6%-30%]@range@ weniger Schaden, und jeder getroffene Feind heilt Euch um 1% Eurer Gesundheit (Nicht stapelbar)",
    -- addon:data.affix_text.during_metamorphosis_your_shadow_cleave:text
    ["During Metamorphosis your Shadow Cleave strikes in both realms: it hits again for @value@75%@value@ @range@[30%-75%]@range@ of its damage (Does not stack)"] = "Während Metamorphose aktiv ist, trifft Euer Schattenspalten in beiden Reichen: Es trifft erneut mit @value@75%@value@ @range@[30%-75%]@range@ seines Schadens (Nicht stapelbar)",
    -- addon:data.affix_text.during_metamorphosis_your_immolation_aur:text
    ["During Metamorphosis, your Immolation Aura leaves Flames of Azzinoth on the ground behind you. Enemies in them burn for @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power every second (Does not stack)"] = "Während Metamorphose aktiv ist, hinterlässt Eure Feuerbrandaura Flammen von Azzinoth auf dem Boden hinter Euch. Feinde darin erleiden jede Sekunde Schaden in Höhe von @value@50%@value@ @range@[10%-50%]@range@ Eurer Zaubermacht (Nicht stapelbar)",
    -- addon:data.affix_text.during_shadow_dance_your_finishing_moves:text
    ["During Shadow Dance, your finishing moves also strike every enemy within 8 yd of the target for @value@40%@value@ @range@[15%-40%]@range@ of their damage as Shadow (Does not stack)"] = "Während Schattentanz aktiv ist, treffen Eure Finishing-Moves zudem jeden Feind im Umkreis von 8 Metern um das Ziel mit @value@40%@value@ @range@[15%-40%]@range@ ihres Schadens als Schattenschaden (Nicht stapelbar)",
    -- addon:data.petdesc.26541:text
    ["During the majestic Winter Veil celebration, these faithful companions spread joy throughout the land. The rest of the year, they are busy."] = "Während des prächtigen Winterhauchfests verbreiten diese treuen Begleiter Freude im ganzen Land. Den Rest des Jahres über sind sie beschäftigt.",
