    -- addon:data.graveyard.duskwood_darkshire:text
    ["Duskwood, Darkshire"] = "Dämmerwald, Dunkelhain",
    -- addon:data.graveyard.duskwood_ravenhill:text
    ["Duskwood, Ravenhill"] = "Dämmerwald, Rabenflucht",
    -- addon:data.graveyard.dustwallow_marsh_brackenwall_village:text
    ["Dustwallow Marsh, Brackenwall Village"] = "Düstermarschen, Brackenwall",
    -- addon:data.graveyard.dustwallow_marsh_mudsprocket:text
    ["Dustwallow Marsh, Mudsprocket"] = "Düstermarschen, Morastwinkel",
    -- addon:data.graveyard.dustwallow_marsh_tabetha_s:text
    ["Dustwallow Marsh, Tabetha's"] = "Düstermarschen, Tabethas Hütte",
    -- addon:data.graveyard.dustwallow_marsh_theramore_isle:text
    ["Dustwallow Marsh, Theramore Isle"] = "Düstermarschen, Die Insel Theramore",
    -- addon:data.mountdesc.43900:text
    ["Dwarves attribute this breed's even temperament to rigorous training, but other races argue that a daily diet of strong ale has something to do with it."] = "Die Zwerge führen das ausgeglichene Wesen dieser Rasse auf strenges Training zurück, doch andere Völker meinen, dass eine tägliche Ration starken Biers auch etwas damit zu tun hat.",
    -- addon:core.dying_loses_the_contracts_in_progress_an:text
    ["Dying loses the contracts in progress and the bonus, unless you hold the Reaper's Pact. Accepting death ends the run: its ashes are banked without the bonus."] = "Wenn Ihr sterbt, verliert Ihr die laufenden Verträge und den Bonus, es sei denn, Ihr besitzt den Reaper's Pact. „Den Tod akzeptieren“ beendet den Durchlauf: Seine Asche wird ohne den Bonus gutgeschrieben.",
    -- addon:core.dying_loses_the_contracts_in:text
    ["Dying loses the contracts in progress; the bonus stays. Accepting death ends the run: its ashes are banked without the bonus, and the bonus is gone."] = "Wenn Ihr sterbt, verliert Ihr die laufenden Verträge; der Bonus bleibt. „Den Tod akzeptieren“ beendet den Durchlauf: Seine Asche wird ohne den Bonus gutgeschrieben, und der Bonus verfällt.",
    -- addon:extraction.label_engrave:text
    ["ENGRAVE"] = "GRAVIEREN",
    -- addon:data.affix_text.each_arcane_missiles_missile_has_a_30_ch:text
    ["Each Arcane Missiles missile has a 30 % chance to split onto another enemy within 15 yd for @value@75%@value@ @range@[30%-75%]@range@ of its damage (Does not stack)"] = "Jedes Geschoss von Arkane Geschosse hat eine Chance von 30%, auf einen anderen Feind im Umkreis von 15 Metern überzuspringen und @value@75%@value@ @range@[30%-75%]@range@ seines Schadens zu verursachen (Nicht stapelbar)",
    -- addon:data.affix_text.each_killing_spree_strike_calls_a_darkfi:text
    ["Each Killing Spree strike calls a Darkfiend that strikes the same enemy for @value@300%@value@ @range@[60%-300%]@range@ of your Attack Power as Shadow damage (Does not stack)"] = "Jeder Treffer von Mordlust ruft einen Dunkelunhold herbei, der denselben Feind trifft und Schattenschaden in Höhe von @value@300%@value@ @range@[60%-300%]@range@ Eurer Angriffskraft verursacht (Nicht stapelbar)",
    -- addon:data.affix_text.each_killing_spree_strike_leaves_a_ghost:text
    ["Each Killing Spree strike leaves a ghostly echo that strikes the same enemy again for @value@60%@value@ @range@[20%-60%]@range@ of the damage (Does not stack)"] = "Jeder Treffer von Mordlust hinterlässt ein geisterhaftes Echo, das denselben Feind erneut mit @value@60%@value@ @range@[20%-60%]@range@ des Schadens trifft (Nicht stapelbar)",
    -- addon:data.affix_text.each_killing_spree_strike_restores_value:text
    ["Each Killing Spree strike restores @value@16@value@ @range@[6-16]@range@ energy (Does not stack)"] = "Jeder Treffer von Mordlust stellt @value@16@value@ @range@[6-16]@range@ Energie wieder her (Nicht stapelbar)",
    -- addon:data.affix_text.each_lightning_shield_charge_that_strike:text
    ["Each Lightning Shield charge that strikes an attacker also reduces your damage taken by @value@6%@value@ @range@[2%-6%]@range@ for 4 sec (Does not stack)"] = "Jede Aufladung von Blitzschlagschild, die einen Angreifer trifft, verringert außerdem Euren erlittenen Schaden 4 Sek. lang um @value@6%@value@ @range@[2%-6%]@range@ (Nicht stapelbar)",
    -- addon:core.each_soul_ash_resurrection_costs:text
    ["Each Soul Ash resurrection costs more than the last. Counters reset on accept death."] = "Jede Wiederbelebung mit Seelenasche kostet mehr als die letzte. Die Zähler werden zurückgesetzt, wenn Ihr „Den Tod akzeptieren“ wählt.",
    -- addon:data.affix_text.each_starfall_ends_with_a_meteor_on_your:text
    ["Each Starfall ends with a meteor on your target: @value@600%@value@ @range@[120%-600%]@range@ of your Spell Power as Fire damage to enemies within 8 yd, leaving burning ground for 4 sec (Does not stack)"] = "Jeder Sternenregen endet mit einem Meteor auf Eurem Ziel: Feinde im Umkreis von 8 Metern erleiden Feuerschaden in Höhe von @value@600%@value@ @range@[120%-600%]@range@ Eurer Zaubermacht, und der Boden brennt 4 Sek. lang (Nicht stapelbar)",
    -- addon:data.affix_text.each_void_bolt_tears_open_a_void_zone_un:text
    ["Each Void Bolt tears open a Void Zone under its target: non-boss enemies within 6 yd are dragged to its center, and every enemy within 6 yd takes @value@15%@value@ @range@[5%-15%]@range@ more damage from your Shadow spells for 4 sec (Does not stack)"] = "Jeder Leereblitz reißt eine Zone der Leere unter seinem Ziel auf: Feinde im Umkreis von 6 Metern, die keine Bosse sind, werden in ihre Mitte gezogen, und jeder Feind im Umkreis von 6 Metern erleidet 4 Sek. lang @value@15%@value@ @range@[5%-15%]@range@ mehr Schaden durch Eure Schattenzauber (Nicht stapelbar)",
    -- addon:data.affix_text.each_ally_healed_by_chain_heal_gets_a_wa:text
    ["Each ally healed by Chain Heal gets a water globule at its feet for 10 sec. The first injured ally to touch it, the healed ally included, is healed for @value@200%@value@ @range@[40%-200%]@range@ of your Spell Power (Does not stack)"] = "Jeder von Kettenheilung geheilte Verbündete erhält 10 Sek. lang eine Wasserkugel zu seinen Füßen. Der erste verletzte Verbündete, der sie berührt, den geheilten Verbündeten eingeschlossen, wird um @value@200%@value@ @range@[40%-200%]@range@ Eurer Zaubermacht geheilt (Nicht stapelbar)",
    -- addon:data.affix_text.each_ally_healed_by_your_radiant_echo_is:text
    ["Each ally healed by your Radiant Echo is cleansed of one poison or disease and healed for @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power over 6 sec (Does not stack)"] = "Jeder von Eurem Strahlenden Echo geheilte Verbündete wird von einem Gift oder einer Krankheit befreit und über 6 Sek. um @value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht geheilt (Nicht stapelbar)",
    -- addon:data.affix_text.each_bolt_of_penance_bounces_to_another:text
    ["Each bolt of Penance bounces to another injured ally within 15 yd for @value@75%@value@ @range@[30%-75%]@range@ of its heal (Does not stack)"] = "Jeder Blitz von Sühne springt auf einen anderen verletzten Verbündeten im Umkreis von 15 Metern über und heilt ihn um @value@75%@value@ @range@[30%-75%]@range@ seiner Heilung (Nicht stapelbar)",
    -- addon:data.affix_text.each_bolt_of_penance_on_an_ally_also_wra:text
    ["Each bolt of Penance on an ally also wraps it in a Twilight Shield absorbing @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power for 8 sec (Does not stack)"] = "Jeder Blitz von Sühne auf einen Verbündeten hüllt diesen zudem 8 Sek. lang in einen Zwielichtschild, der Schaden in Höhe von @value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht absorbiert (Nicht stapelbar)",
    -- addon:raidLockout.each_boss_can_be_looted_2:text
    ["Each boss can be looted once a week (Tuesday 03:00 UTC)."] = "Jeder Boss kann einmal pro Woche geplündert werden (Dienstag 03:00 UTC).",
    -- addon:raidLockout.each_boss_can_be_looted:text
    ["Each boss can be looted once a week. Resets in {soonest}."] = "Jeder Boss kann einmal pro Woche geplündert werden. Wird in {soonest} zurückgesetzt.",
    -- addon:perks.spec_banner_sub:text
    ["Each card is one specialization (icon above its name). Every 10 levels of this run, you will get three echoes of the one you take"] = "Jede Karte steht für eine Spezialisierung (Symbol über ihrem Namen). Alle 10 Stufen dieses Durchlaufs erhaltet Ihr drei Echos der gewählten Spezialisierung",
    -- addon:perks.each_card_is_one_specialization_small_ic:text
    ["Each card is one specialization (small icon on the echo's corner). Every 10 levels of this run, you will get three echoes of the one you take"] = "Jede Karte ist eine Spezialisierung (kleines Symbol in der Ecke des Echos). Alle 10 Stufen dieses Durchlaufs erhaltet Ihr drei Echos der gewählten Spezialisierung",
    -- addon:data.affix_text.each_enemy_hit_by_chain_lightning_calls:text
    ["Each enemy hit by Chain Lightning calls one loa, in order: Eagle (@value@150%@value@ @range@[30%-150%]@range@ of your Spell Power as extra Nature damage), Lynx (you deal 30 % more damage for 10 sec), Bear (absorbs @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power), Dragonhawk (@value@150%@value@ @range@[30%-150%]@range@ of your Spell Power as Fire damage around that enemy). Four loa call Zul'jin's spirit: your next Chain Lightning jumps 8 times (Does not stack)"] = "Jeder von Kettenblitzschlag getroffene Feind ruft der Reihe nach einen Loa herbei: Adler (@value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht als zusätzlicher Naturschaden), Luchs (Ihr verursacht 10 Sek. lang 30% mehr Schaden), Bär (absorbiert @value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht), Drachenfalke (@value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht als Feuerschaden um diesen Feind). Vier Loa rufen den Geist von Zul'jin herbei: Euer nächster Kettenblitzschlag springt 8-mal über (Nicht stapelbar)",
    -- addon:data.affix_text.each_enemy_hit_by_hammer_of_the_righteou:text
    ["Each enemy hit by Hammer of the Righteous reduces the cooldown of Avenger's Shield by @value@1,5@value@ @range@[0,5-1,5]@range@ sec (Does not stack)"] = "Jeder von Hammer der Rechtschaffenen getroffene Feind verringert die Abklingzeit von Schild des Rächers um @value@1,5@value@ @range@[0,5-1,5]@range@ Sek. (Nicht stapelbar)",
    -- addon:data.affix_text.each_enemy_hit_by_whirlwind_gives_you_va:text
    ["Each enemy hit by Whirlwind gives you @value@10@value@ @range@[2-10]@range@ rage (Does not stack)"] = "Jeder von Wirbelwind getroffene Feind gewährt Euch @value@10@value@ @range@[2-10]@range@ Wut (Nicht stapelbar)",
    -- addon:torment.each_extra_item_is_one:text
    ["Each extra item is one more roll on the loot table of the creature or boss chest; the best item it gives is added to the loot.  Not on open-world chests or gathering."] = "Jeder zusätzliche Gegenstand ist ein weiterer Wurf auf die Beutetabelle der Kreatur oder der Bosstruhe; der beste Gegenstand daraus wird der Beute hinzugefügt.  Nicht bei Truhen in der offenen Welt oder beim Sammeln.",
    -- addon:data.affix_text.each_jump_of_chain_heal_also_heals_the_a:text
    ["Each jump of Chain Heal also heals the ally's twilight reflection: another injured ally nearby is healed for @value@40%@value@ @range@[20%-40%]@range@ of the amount (Does not stack)"] = "Jeder Sprung von Kettenheilung heilt auch das Zwielichtspiegelbild des Verbündeten: Ein anderer verletzter Verbündeter in der Nähe wird um @value@40%@value@ @range@[20%-40%]@range@ des Betrags geheilt (Nicht stapelbar)",
    -- addon:data.affix_text.each_jump_of_chain_heal_reduces_the_rema:text
    ["Each jump of Chain Heal reduces the remaining cooldown of your Riptide by @value@0,8@value@ @range@[0,3-0,8]@range@ sec (Does not stack)"] = "Jeder Sprung von Kettenheilung verringert die verbleibende Abklingzeit Eurer Springflut um @value@0,8@value@ @range@[0,3-0,8]@range@ Sek. (Nicht stapelbar)",
    -- addon:data.affix_text.each_jump_of_prayer_of_mending_reduces_t:text
    ["Each jump of Prayer of Mending reduces the remaining cooldown of Circle of Healing by @value@0,6@value@ @range@[0,2-0,6]@range@ sec (Does not stack)"] = "Jeder Sprung von Gebet der Besserung verringert die verbleibende Abklingzeit von Kreis der Heilung um @value@0,6@value@ @range@[0,2-0,6]@range@ Sek. (Nicht stapelbar)",
    -- addon:data.affix_text.each_poison_or_disease_your_cleansing_to:text
    ["Each poison or disease your Cleansing Totem removes also heals the ally for @value@200%@value@ @range@[40%-200%]@range@ of your Spell Power (Does not stack)"] = "Jedes Gift und jede Krankheit, die Euer Totem der Reinigung entfernt, heilt den Verbündeten zusätzlich um @value@200%@value@ @range@[40%-200%]@range@ Eurer Zaubermacht (Nicht stapelbar)",
    -- addon:prestige.each_prestige_fills_this_bar:text
    ["Each prestige fills this bar. Milestones grant rewards: mounts, full transmog sets, titles and an exclusive chat rank icon. Hover a milestone for its details."] = "Jedes Prestige füllt diese Leiste. Meilensteine gewähren Belohnungen: Reittiere, komplette Transmogrifikationssets, Titel und ein exklusives Rangsymbol im Chat. Bewegt den Mauszeiger über einen Meilenstein, um Details zu sehen.",
    -- addon:data.affix_text.each_tick_of_explosive_shot_has_a_value:text
    ["Each tick of Explosive Shot has a @value@12%@value@ @range@[3%-12%]@range@ chance to finish the cooldown of Black Arrow (Does not stack)"] = "Jeder Tick von Explosivschuss hat eine Chance von @value@12%@value@ @range@[3%-12%]@range@, die Abklingzeit von Schwarzer Pfeil zu beenden (Nicht stapelbar)",
    -- addon:data.affix_text.each_tick_of_vampiric_touch_reduces_the:text
    ["Each tick of Vampiric Touch reduces the remaining cooldown of Mind Blast by @value@0,8@value@ @range@[0,3-0,8]@range@ sec (Does not stack)"] = "Jeder Tick von Vampirberührung verringert die verbleibende Abklingzeit von Gedankenschlag um @value@0,8@value@ @range@[0,3-0,8]@range@ Sek. (Nicht stapelbar)",
    -- addon:data.affix_text.each_tick_of_your_corruption_grants_you:text
    ["Each tick of your Corruption grants you a shell absorbing @value@25%@value@ @range@[5%-25%]@range@ of your Spell Power, stacking up to 5 times (Does not stack)"] = "Jeder Tick Eurer Verderbnis gewährt Euch eine Hülle, die Schaden in Höhe von @value@25%@value@ @range@[5%-25%]@range@ Eurer Zaubermacht absorbiert, bis zu 5-mal stapelbar (Nicht stapelbar)",
    -- addon:data.affix_text.each_tick_of_your_unstable_affliction_ha:text
    ["Each tick of your Unstable Affliction has a 20 % chance to leave a pool of Consumption under the target for 6 sec: @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power as Shadow damage every second to enemies inside (Does not stack)"] = "Jeder Tick von Instabiles Gebrechen hat eine Chance von 20%, 6 Sek. lang eine Lache der Verzehrung unter dem Ziel zu hinterlassen: Feinde darin erleiden jede Sekunde Schattenschaden in Höhe von @value@50%@value@ @range@[10%-50%]@range@ Eurer Zaubermacht (Nicht stapelbar)",
    -- addon:toolbelt.tip_auto_sell:text
    ["Each time you leave combat, everything matching the rules below is sold."] = "Jedes Mal, wenn Ihr den Kampf verlasst, wird alles verkauft, was den untenstehenden Regeln entspricht.",
    -- addon:toolbelt.tip_auto_repair:text
    ["Each time you leave combat, your gear is repaired if it took damage."] = "Jedes Mal, wenn Ihr den Kampf verlasst, wird Eure Ausrüstung repariert, falls sie beschädigt wurde.",
    -- addon:data.affix_text.each_time_your_dark_detonation_detonates:text
    ["Each time your Dark Detonation detonates your periodic spells, a wave of darkness bursts from the target: @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power as Shadow damage to enemies within 10 yd (Does not stack)"] = "Jedes Mal, wenn Eure Dunkle Detonation Eure regelmäßigen Zauber detonieren lässt, bricht eine Welle der Dunkelheit aus dem Ziel hervor: Feinde im Umkreis von 10 Metern erleiden Schattenschaden in Höhe von @value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht (Nicht stapelbar)",
    -- addon:data.affix_text.each_time_your_lightning_bolt_forks_it_h:text
    ["Each time your Lightning Bolt forks, it has a @value@30%@value@ @range@[10%-30%]@range@ chance to finish the cooldown of Lava Burst (Does not stack)"] = "Jedes Mal, wenn sich Euer Blitzschlag gabelt, hat er eine Chance von @value@30%@value@ @range@[10%-30%]@range@, die Abklingzeit von Lavaexplosion zu beenden (Nicht stapelbar)",
    -- addon:data.affix_text.each_time_your_lightning_bolt_forks_the:text
    ["Each time your Lightning Bolt forks, the rhino loa charges the new target: @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power as Nature damage, and non-boss enemies are knocked back (Does not stack)"] = "Jedes Mal, wenn sich Euer Blitzschlag verzweigt, stürmt der Nashorn-Loa auf das neue Ziel: Naturschaden in Höhe von @value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht, und Feinde, die keine Bosse sind, werden zurückgestoßen (Nicht stapelbar)",
    -- addon:data.boss.eadric_the_pure:text
    ["Eadric the Pure"] = "Eadric der Reine",
    -- addon:skillTree.earn_soul_ashes_to_advance:text
    ["Earn Soul Ashes to advance toward your next milestone."] = "Verdient Euch Seelenasche, um zum nächsten Meilenstein voranzukommen.",
    -- addon:skillTree.earned_at_the_hero_s:text
    ["Earned at the Hero's Call Board: every crafting contract you claim pays one. Never reset."] = "Verdient am Brett des Heldenrufs: Jeder Handwerksvertrag, den Ihr einlöst, bringt eine ein. Wird nie zurückgesetzt.",
    -- addon:playerRun.earned_from_every_kill_that:text
    ["Earned from every kill that gives experience. Hover the counter to see your multiplier: |cffffd700achievements|r and |cffffd700Prestige|r raise it for good."] = "Wird durch jeden Sieg verdient, der Erfahrung einbringt. Bewegt den Mauszeiger über den Zähler, um Euren Multiplikator zu sehen: |cffffd700Erfolge|r und |cffffd700Prestige|r erhöhen ihn dauerhaft.",
    -- addon:extraction.earned_in_label:text
    ["Earned in {label}."] = "Erworben in {label}.",
    -- addon:core.earned_this_run_banked_when:text
    ["Earned this run. Banked when you make an offering at a Spirit Healer or accept death."] = "In diesem Durchlauf verdient. Wird gutgeschrieben, wenn Ihr bei einem Geistheiler eine Opfergabe darbringt oder „Den Tod akzeptieren“ wählt.",
    -- addon:core.earned_this_run_banked_with:text
    ["Earned this run. Banked with your Soul Ashes."] = "In diesem Durchlauf verdient. Wird mit Eurer Seelenasche gutgeschrieben.",
