    -- addon:options.enables_vector_based_msdf_font:text
    ["Enables vector-based (MSDF) font rendering, dramatically improving glyph quality. Requires a UI reload to take effect."] = "Aktiviert vektorbasierte (MSDF) Schriftdarstellung, die die Glyphenqualität drastisch verbessert. Erfordert ein Neuladen der Benutzeroberfläche, um wirksam zu werden.",
