    -- addon:extraction.enchantments_gems_and_its_affix_are_kept:text
    ["Enchantments, gems and its affix are kept."] = "Verzauberungen, Edelsteine und sein Affix bleiben erhalten.",
    -- addon:data.affix_text.enemies_frozen_by_your_frost_nova_are_ta:text
    ["Enemies frozen by your Frost Nova are tainted. When the freeze breaks, each one bursts for @value@200%@value@ @range@[40%-200%]@range@ of your Spell Power as Nature damage and freezes enemies around it for 2 sec. A burst cannot trigger another burst (Does not stack)"] = "Von Eurer Frostnova eingefrorene Feinde werden besudelt. Bricht das Eis, zerbirst jeder von ihnen, verursacht Naturschaden in Höhe von @value@200%@value@ @range@[40%-200%]@range@ Eurer Zaubermacht und friert Feinde in seiner Umgebung 2 Sek. lang ein. Ein Zerbersten kann kein weiteres auslösen (Nicht stapelbar)",
    -- addon:data.affix_text.enemies_killed_by_scourge_strike_explode:text
    ["Enemies killed by Scourge Strike explode after 2 sec: @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power as Shadow damage to enemies within 8 yd (Does not stack)"] = "Von Geißelstoß getötete Feinde explodieren nach 2 Sek.: Feinde im Umkreis von 8 Metern erleiden Schattenschaden in Höhe von @value@150%@value@ @range@[30%-150%]@range@ Eurer Angriffskraft (Nicht stapelbar)",
    -- addon:data.affix_text.enemies_killed_by_scourge_strike_give_yo:text
    ["Enemies killed by Scourge Strike give you @value@30@value@ @range@[10-30]@range@ runic power and explode in plague after 2 sec for 20 % of your Attack Power as Shadow damage to enemies within 8 yd (Does not stack)"] = "Von Geißelstoß getötete Feinde gewähren Euch @value@30@value@ @range@[10-30]@range@ Runenmacht und explodieren nach 2 Sek. in einer Seuche, die Feinden im Umkreis von 8 Metern Schattenschaden in Höhe von 20% Eurer Angriffskraft zufügt (Nicht stapelbar)",
    -- addon:data.affix_text.enemies_standing_in_your_consecration_de:text
    ["Enemies standing in your Consecration deal @value@15%@value@ @range@[3%-15%]@range@ less damage to your allies and are slowed by 20 % (Does not stack)"] = "Feinde in Eurer Weihe fügen Euren Verbündeten @value@15%@value@ @range@[3%-15%]@range@ weniger Schaden zu und werden um 20% verlangsamt (Nicht stapelbar)",
    -- addon:options.enemy_nameplate_hitbox_height:text
