    ["Equipped item level |cffffffff{equippedIlvl}|r\nCaches opened |cffffffff{cachesOpened}|r"] = "Gegenstandsstufe der Ausrüstung |cffffffff{equippedIlvl}|r\nGeöffnete Behälter |cffffffff{cachesOpened}|r",
    -- addon:data.boss.eredar_twins:text
