    -- addon:data.boss.escaped_from_arthas:text
    ["Escaped from Arthas"] = "Flucht vor Arthas",
    -- addon:data.petdesc.49964:text
    ["Ethereal soul-traders will travel with those who can free the essences they need from unruly hosts."] = "Astrale Seelenhändler reisen mit jenen, die die benötigten Essenzen aus widerspenstigen Wirten befreien können.",
    -- addon:data.affix_family.evasive:text
    ["Evasive"] = "Ausweichend",
    -- addon:data.mountdesc.60025:text
    ["Even the Draconic Native Association tests proved inconclusive in determining if the albino drake is related to a known dragonflight. -Breanni"] = "Selbst die Tests der Vereinigung drachischer Ureinwohner konnten nicht klären, ob der Albinodrache mit einem bekannten Drachenschwarm verwandt ist. - Breanni",
    -- addon:data.mountdesc.55164:text
    ["Even the dead need a lift every now and then."] = "Selbst die Toten brauchen hin und wieder eine Mitfahrgelegenheit.",
