    -- addon:torment.open_world:text
    ["Open world"] = "Offene Welt",
    -- addon:torment.open_world_capped_at_torment:text
    ["Open world (capped at Torment X)"] = "Offene Welt (auf Qual X begrenzt)",
    -- addon:torment.open_world_you_and_your_group_enter_a_pr:text
    ["Open world: you and your group enter a private phase - nobody else sees your fight. A portal takes you back once it is held ({min} minutes, then you are sent back anyway). If you die, you are out of the hold at once: back to the world, no reward, no way back - the others hold on. Leaving the map also takes you out."] = "Offene Welt: Ihr und Eure Gruppe betretet eine private Phase - niemand sonst sieht Euren Kampf. Ein Portal bringt Euch zurück, sobald die Stellung gehalten ist ({min} Minuten, danach werdet Ihr ohnehin zurückgeschickt). Sterbt Ihr, scheidet Ihr sofort aus: zurück in die Welt, keine Belohnung, kein Weg zurück - die anderen halten weiter durch. Verlasst Ihr die Karte, scheidet Ihr ebenfalls aus.",
    -- addon:skillTree.open_your_skill_tree:text
    ["Open your Skill Tree."] = "Öffnet Euren Aschebaum.",
    -- addon:checkpoint.open_your_world_map_to:text
