    ["Opening Assault"] = "Eröffnungsangriff",
    -- addon:toolbelt.opens_a_merchant_window_right_here_buy_t:text
    ["Opens a merchant window right here. Buy trade goods, sell any item by hand, buy back, repair."] = "Öffnet direkt hier ein Händlerfenster. Kauft Handwerkswaren, verkauft beliebige Gegenstände von Hand, kauft zurück, repariert.",
    -- addon:toolbelt.menu_anvil_tip:text
    ["Opens the Enchanted Anvil right here: extract affixes, engrave them and upgrade to Torment."] = "Öffnet den Verzauberten Amboss direkt hier: Affixe extrahieren, eingravieren und auf Qual aufwerten.",
    -- addon:toolbelt.menu_callboard_tip:text
    ["Opens the Hero's Call Board right here: take contracts and claim their rewards."] = "Öffnet das Brett des Heldenrufs direkt hier: Verträge annehmen und ihre Belohnungen einfordern.",
    -- addon:toolbelt.menu_auction_tip:text
    ["Opens the auction house right here: browse, bid and sell."] = "Öffnet das Auktionshaus direkt hier: stöbern, bieten und verkaufen.",
    -- addon:toolbelt.menu_guild_bank_tip:text
    ["Opens your guild's bank right here, wherever you are."] = "Öffnet die Bank Eurer Gilde direkt hier, wo auch immer Ihr seid.",
    -- addon:toolbelt.menu_mailbox_tip:text
    ["Opens your mailbox right here: read, take and send mail."] = "Öffnet Euren Briefkasten direkt hier: Post lesen, entnehmen und versenden.",
    -- addon:toolbelt.menu_bank_tip:text
    ["Opens your personal bank right here, wherever you are."] = "Öffnet Eure persönliche Bank direkt hier, wo immer Ihr seid.",
