    -- addon:data.mountdesc.17462:text
    ["The Forsaken believe that without a purpose, even beasts of burden suffer in undeath."] = "Die Verlassenen glauben, dass selbst Lasttiere im Untod leiden, wenn sie keine Aufgabe haben.",
