    -- addon:data.mountdesc.32242:text
    ["The Horde had dragons, we had the gryphons. We won that war. - Ilsa Blusterbrew"] = "Die Horde hatte Drachen, wir hatten die Greifen. Wir haben diesen Krieg gewonnen. - Ilsa Trubelbräu",
    -- addon:data.prestige.the_horseman_s_burning_greatblade:text
