    -- addon:skillTree.the_prestige_sector_of_the:text
    ["The Prestige sector of the tree: talents, echoes, resurrections, experience."] = "Der Prestige-Sektor des Baums: Talente, Echos, Wiederbelebungen, Erfahrung.",
    -- addon:callboard.the_professions_sector_of_the:text
    ["The Professions sector of the tree: gathering, crafting and the Torment recipes."] = "Der Berufsbereich des Baums: Sammeln, Herstellen und die Rezepte der Qual.",
    -- addon:data.boss.the_prophet_skeram:text
