    -- addon:data.boss.the_ravenian:text
    ["The Ravenian"] = "Der Ravenier",
    -- addon:reaper.the_reaper_does_not_answer:text
    ["The Reaper does not answer on this realm."] = "Der Schnitter antwortet auf diesem Realm nicht.",
    -- addon:playerRun.the_reaper_s_gaze:text
    ["The Reaper's Gaze"] = "Der Blick des Schnitters",
    -- addon:data.instance.the_ruby_sanctum:text
    ["The Ruby Sanctum"] = "Das Rubinsanktum",
    -- addon:data.waystone.the_sepulcher_silverpine_forest:text
    ["The Sepulcher, Silverpine Forest"] = "Das Grabmal, Silberwald",
    -- addon:data.boss.the_seven:text
    ["The Seven"] = "Die Sieben",
    -- addon:data.waystone.the_shadow_vault_icecrown:text
    ["The Shadow Vault, Icecrown"] = "Das Schattengewölbe, Eiskrone",
    -- addon:data.mountdesc.59797:text
    ["The Sons of Hodir believe that riding an ice-white mammoth will protect the rider from frostbite and snow blindness."] = "Die Söhne Hodirs glauben, dass der Ritt auf einem eisweißen Mammut den Reiter vor Erfrierungen und Schneeblindheit schützt.",
    -- addon:data.waystone.the_stair_of_destiny_hellfire_peninsula:text
    ["The Stair of Destiny, Hellfire Peninsula"] = "Die Stufen des Schicksals, Höllenfeuerhalbinsel",
    -- addon:data.waystone.the_stockade:text
    ["The Stockade"] = "Das Verlies",
    -- addon:data.mountdesc.59996:text
    ["The Storm Peaks! There we will find the beast strong enough to bear me into battle. -Skadi the Ruthless"] = "Die Sturmgipfel! Dort werden wir die Bestie finden, die stark genug ist, mich in die Schlacht zu tragen. - Skadi der Skrupellose",
    -- addon:data.mountdesc.23510:text
    ["The Stormpike clan's mount trainers have a tradition of etching their names onto the left horn of every battle ram they raise."] = "Die Reittierausbilder des Sturmlanzenklans pflegen die Tradition, ihre Namen in das linke Horn jedes Kampfwidders zu ritzen, den sie aufziehen.",
    -- addon:data.waystone.the_stormspire_netherstorm:text
    ["The Stormspire, Netherstorm"] = "Die Sturmsäule, Nethersturm",
    -- addon:data.mountdesc.66088:text
    ["The Sunreavers of Dalaran select only the swiftest and most formidable of dragonhawks as their mounts."] = "Die Sonnenhäscher von Dalaran wählen nur die schnellsten und furchteinflößendsten Drachenfalken als Reittiere aus.",
    -- addon:data.instance.the_sunwell:text
    ["The Sunwell"] = "Der Sonnenbrunnen",
    -- addon:data.waystone.the_temple_of_atal_hakkar:text
    ["The Temple of Atal'Hakkar"] = "Der Tempel von Atal'Hakkar",
    -- addon:toolbelt.chat_loading:text
    ["The Toolbelt is still loading. Try again in a moment."] = "Der Werkzeugkasten wird noch geladen. Versucht es gleich noch einmal.",
    -- addon:data.boss.the_unforgiven:text
    ["The Unforgiven"] = "Der Unverziehene",
    -- addon:voidStorage.the_void_storage:text
    ["The Void Storage"] = "Das Leerenlager",
    -- addon:extBank.the_warband_bank_is_locked:text
    ["The Warband Bank is locked.\n\nUnlock it once and every character of your account\nshares its bags and its gold."] = "Die Kriegsmeutenbank ist gesperrt.\n\nSchaltet sie einmal frei, und alle Charaktere Eures Accounts\nteilen die Taschen und das Gold der Bank.",
    -- addon:shop.token_title:text
    ["The WoW Token"] = "Die WoW-Marke",
    -- addon:data.mountdesc.44153:text
    ["The backbone of the Alliance air force is comprised predominantly of gnomish flying machines due to their maneuverability and speed."] = "Das Rückgrat der Luftstreitkräfte der Allianz besteht überwiegend aus gnomischen Flugmaschinen, da diese so wendig und schnell sind.",
    -- addon:data.petdesc.62508:text
    ["The bears of Dun Morogh are prized for their hardiness, loyalty, and combat prowess. Their time among the dwarves does little to curb their ferocity."] = "Die Bären von Dun Morogh werden für ihre Zähigkeit, Treue und Kampfkraft geschätzt. Ihre Zeit unter den Zwergen mindert ihre Wildheit kaum.",
    -- addon:data.petdesc.65381:text
    ["The bouncy gurloc is a distant cousin of the murloc."] = "Der hüpfende Gurloc ist ein entfernter Vetter des Murlocs.",
    -- addon:data.petdesc.10716:text
    ["The brown snake is native to Horde-controlled territories. It seems unremarkable until its victims are within range."] = "Die braune Schlange ist in den Gebieten der Horde heimisch. Sie wirkt unscheinbar, bis ihre Opfer in Reichweite sind.",
    -- addon:prestige.the_button_opens_when_both:text
    ["The button opens when both are met: enough Soul Ashes committed to your Skill Tree, and at least 750 banked Soul Shards, so the reset always pays at least one Soul Essence.\n\nHover the locked button to see which one is still missing."] = "Die Schaltfläche wird verfügbar, wenn beides erfüllt ist: genug Seelenasche in Euren Aschebaum investiert und mindestens 750 eingezahlte Seelensplitter, damit das Zurücksetzen immer mindestens eine Seelenessenz einbringt.\n\nBewegt den Mauszeiger über die gesperrte Schaltfläche, um zu sehen, was noch fehlt.",
    -- addon:prestige.the_button_opens_when_both_are_met_enoug:text
    ["The button opens when both are met: enough Soul Ashes committed to your Skill Tree, and enough banked Soul Shards for one Soul Essence, so the reset always pays at least one Soul Essence.\n\nHover the locked button to see which one is still missing."] = "Die Schaltfläche wird verfügbar, wenn beides erfüllt ist: genug Seelenasche in Euren Aschebaum investiert und genug eingezahlte Seelensplitter für eine Seelenessenz, damit das Zurücksetzen immer mindestens eine Seelenessenz einbringt.\n\nBewegt den Mauszeiger über die gesperrte Schaltfläche, um zu sehen, was noch fehlt.",
    -- addon:skillTree.the_cast_was_interrupted_your_changes_we:text
    ["The cast was interrupted, your changes were not applied."] = "Der Zauber wurde unterbrochen, Eure Änderungen wurden nicht übernommen.",
    -- addon:data.petdesc.61351:text
    ["The cobras of Azeroth are renowned for their fast-acting venom and swift strikes."] = "Die Kobras von Azeroth sind berühmt für ihr schnell wirkendes Gift und ihre flinken Bisse.",
    -- addon:data.petdesc.10688:text
    ["The cockroach is usually an impulse buy. Its owners have a hard time parting with it even after numerous attempts."] = "Die Kakerlake ist meist ein Spontankauf. Ihre Besitzer können sich auch nach zahlreichen Versuchen nur schwer von ihr trennen.",
    -- addon:journal.the_complete_catalog_echoes_you:text
    ["The complete catalog. Echoes you currently hold are not repeated here: they already sit on the left.\n\nEchoes with a |cffffd700book badge|r are sealed inside Tomes: greyed until you loot and learn their tome, then permanently yours."] = "Der vollständige Katalog. Echos, die Ihr derzeit besitzt, werden hier nicht wiederholt: Sie stehen bereits links.\n\nEchos mit einem |cffffd700Buchsymbol|r sind in Folianten versiegelt: ausgegraut, bis Ihr ihren Folianten erbeutet und erlernt habt, danach gehören sie für immer Euch.",
    -- addon:core.the_count_starts_again_at_the_weekly_res:text
    ["The count starts again at the weekly reset."] = "Die Zählung beginnt mit der wöchentlichen Zurücksetzung von vorn.",
    -- addon:data.petdesc.10717:text
    ["The crimson snake is favored among the Darkspear trolls for not only its vicious nature, but also its steadfast loyalty."] = "Die purpurrote Schlange ist bei den Dunkelspeertrollen nicht nur wegen ihres bösartigen Wesens beliebt, sondern auch wegen ihrer unerschütterlichen Treue.",
    -- addon:data.petdesc.43697:text
    ["The crocolisk's hide and meat are prized by hunters, but the beast is ferocious and seldom taken by surprise."] = "Haut und Fleisch des Krokilisken sind bei Jägern begehrt, doch das Tier ist wild und lässt sich selten überraschen.",
    -- addon:callboard.the_currency_of_the_soul:text
    ["The currency of the Soul Ash Tree: every ordinary node, the flat stats, the mechanics and the infinite wells."] = "Die Währung des Seelenaschebaums: jeder gewöhnliche Knoten, die festen Werte, die Mechaniken und die unendlichen Quellen.",
    -- addon:data.petdesc.67414:text
    ["The demand for this purple-skinned breed has drastically reduced the raptor population near the Wailing Caverns."] = "Die Nachfrage nach dieser purpurhäutigen Art hat die Raptorenbestände nahe den Höhlen des Wehklagens drastisch verringert.",
    -- addon:playerRun.the_dungeon_runs_at_the:text
    ["The dungeon runs at the difficulty picked in the Dungeon Finder; your own difficulty returns when you leave."] = "Der Dungeon läuft auf der im Dungeonbrowser gewählten Schwierigkeit; Eure eigene Schwierigkeit gilt wieder, sobald Ihr ihn verlasst.",
    -- addon:data.mountdesc.22720:text
    ["The dwarves value their ram companions for their fearlessness charging into battle."] = "Die Zwerge schätzen ihre Widder für die Furchtlosigkeit, mit der sie in die Schlacht stürmen.",
    -- addon:collections.gs_transmogrify_illusion_invalid_item:text
    ["The equipped item cannot be transmogrified with enchants."] = "Der angelegte Gegenstand kann nicht mit Verzauberungen transmogrifiziert werden.",
    -- addon:data.petdesc.35156:text
    ["The ethereal Rashaad began breeding these enigmatic creatures after learning of their ability to feed on arcane energies."] = "Der Astrale Rashaad begann, diese rätselhaften Geschöpfe zu züchten, nachdem er erfahren hatte, dass sie sich von arkaner Energie ernähren können.",
    -- addon:data.mountdesc.72286:text
    ["The famous steed of Arthas Menethil, who serves its master in life and in death.  Riding him is truly a feat of strength."] = "Das berühmte Streitross von Arthas Menethil, das seinem Meister im Leben wie im Tod dient. Es zu reiten ist wahrlich eine Heldentat.",
    -- addon:data.affix_text.the_fifth_frostbolt_on_the_same_target_f:text
    ["The fifth Frostbolt on the same target finishes the cooldown of Frost Nova and reduces the cooldown of Deep Freeze by @value@6@value@ @range@[2-6]@range@ sec (Does not stack)"] = "Der fünfte Frostblitz auf dasselbe Ziel beendet die Abklingzeit von Frostnova und verringert die Abklingzeit von Tieffrieren um @value@6@value@ @range@[2-6]@range@ Sek. (Nicht stapelbar)",
    -- addon:trials.the_first_wave_approaches:text
    ["The first wave approaches"] = "Die erste Welle naht",
    -- addon:data.mountdesc.54753:text
    ["The frost vrykul believe that wearing a necklace of polar bear claws will grant them otherworldly strength."] = "Die Frostvrykul glauben, dass das Tragen einer Halskette aus Eisbärenklauen ihnen übernatürliche Stärke verleiht.",
    -- addon:raidFinder.the_group:text
    ["The group"] = "Die Gruppe",
    -- addon:callboard.the_higher_the_item_level:text
    ["The higher the item level you have ever worn, the more contracts a cache asks for."] = "Je höher die Gegenstandsstufe, die Ihr jemals getragen habt, desto mehr Verträge verlangt ein Behälter.",
    -- addon:torment.the_hold:text
    ["The hold"] = "Die Stellung",
    -- addon:data.petdesc.10682:text
    ["The jungle trolls train these birds to mimic calls for help in order to lure unsuspecting travelers into traps."] = "Die Dschungeltrolle richten diese Vögel darauf ab, Hilferufe nachzuahmen, um ahnungslose Reisende in Fallen zu locken.",
    -- addon:core.the_killing_blow_was_not:text
    ["The killing blow was not recorded."] = "Der tödliche Schlag wurde nicht aufgezeichnet.",
    -- addon:data.mountdesc.16056:text
    ["The lack of spots or stripes marks this beast as a descendant of the most ancient frostsaber line."] = "Das Fehlen von Flecken oder Streifen weist dieses Tier als Nachfahren der ältesten Frostsäblerlinie aus.",
    -- addon:data.mountdesc.24252:text
    ["The last known Zulian tigers were kept by High Priest Thekal, deep within Zul'Gurub.  They are said to have been hunted into extinction."] = "Die letzten bekannten zulianischen Tiger wurden von Hohepriester Thekal tief in Zul'Gurub gehalten. Man sagt, sie seien bis zur Ausrottung gejagt worden.",
    -- addon:data.petdesc.10676:text
    ["The last person who tried to housebreak this cat quickly learned that a soiled rug is better than a shredded everything-else."] = "Der Letzte, der versuchte, diese Katze stubenrein zu machen, lernte schnell, dass ein verschmutzter Teppich besser ist, als wenn alles andere zerfetzt wird.",
    -- addon:data.affix_text.the_last_tick_of_explosive_shot_scatters:text
    ["The last tick of Explosive Shot scatters 3 explosive orbs around the target. Each explodes after 2 sec for @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power as Fire damage to enemies within 4 yd (Does not stack)"] = "Der letzte periodische Schaden von Explosivschuss verstreut 3 explosive Kugeln um das Ziel. Jede explodiert nach 2 Sek. und verursacht @value@150%@value@ @range@[30%-150%]@range@ Eurer Angriffskraft als Feuerschaden an Feinden in einem Umkreis von 4 Metern (Nicht stapelbar)",
    -- addon:data.petdesc.23811:text
    ["The legendary ale frog was believed to be extinct until the strange brews at the Darkmoon Faire brought them out of hiding."] = "Der legendäre Bierfrosch galt als ausgestorben, bis die seltsamen Gebräue des Dunkelmond-Jahrmarkts ihn aus seinem Versteck lockten.",
    -- addon:data.petdesc.62562:text
    ["The long-term effects of the contamination caused by the Exodar are still under observation."] = "Die langfristigen Folgen der durch die Exodar verursachten Verseuchung werden noch immer beobachtet.",
    -- addon:toolbelt.tip_remote:text
    ["The loot of everything that dies near you is picked up for you, filtered by the rules below."] = "Die Beute von allem, was in Eurer Nähe stirbt, wird für Euch aufgehoben, gefiltert nach den untenstehenden Regeln.",
    -- addon:toolbelt.menu_eye_tip:text
    ["The loot of everything that dies near you is picked up for you. Filter what you keep."] = "Die Beute von allem, was in Eurer Nähe stirbt, wird für Euch aufgehoben. Filtert, was Ihr behaltet.",
    -- addon:toolbelt.panel_eye_sub:text
    ["The loot of everything that dies near you, picked up for you."] = "Die Beute von allem, was in Eurer Nähe stirbt, wird für Euch aufgehoben.",
    -- addon:data.petdesc.39181:text
    ["The magical energies released during Skywing's transformation back into his true arakkoa form liberated this poor creature, a fledgling bird imprisoned by Luanga in order to power his fowl curse."] = "Die magischen Energien, die bei Wolkenschwinges Rückverwandlung in seine wahre Arakkoa-Gestalt frei wurden, befreiten dieses arme Geschöpf, einen jungen Vogel, den Luanga eingesperrt hatte, um seinen Federvieh-Fluch zu speisen.",
    -- addon:data.mountdesc.65642:text
    ["The mirror's not so you can look back, but so your foes can see something besides your tailpipes. -Rillie Spindlenut"] = "Der Spiegel ist nicht dazu da, dass Ihr zurückblicken könnt, sondern damit Eure Feinde noch etwas anderes sehen als Eure Auspuffrohre. -Rillie Spindelnuss",
    -- addon:data.mountdesc.28828:text
    ["The moods of these tempestuous mounts are known to shift as unpredictably and as violently as their physical forms."] = "Die Launen dieser stürmischen Reittiere wandeln sich bekanntermaßen ebenso unberechenbar und heftig wie ihre Gestalt.",
    -- addon:data.mountdesc.37015:text
    ["The most aggressive nether drakes were awarded those heroes who showed significant prowess and commitment in the gladiatorial arena."] = "Die aggressivsten Netherdrachen wurden jenen Helden verliehen, die in der Gladiatorenarena bemerkenswertes Können und große Hingabe bewiesen.",
    -- addon:data.mountdesc.61229:text
    ["The nice thing is that when they attack, blood almost never stains their feathers. -Mei Francis"] = "Das Schöne ist, dass bei ihren Angriffen fast nie Blut ihr Gefieder befleckt. - Mei Francis",
    -- addon:professionBook.the_number_of_main_professions_you_can_l:text
    ["The number of main professions you can learn is limited. Jack of All Trades nodes in the Skill Tree unlock more profession slots."] = "Die Anzahl der Hauptberufe, die Ihr erlernen könnt, ist begrenzt. Knoten „Tausendsassa“ im Aschebaum schalten weitere Berufsplätze frei.",
    -- addon:data.mountdesc.24242:text
    ["The only known Razzashi Raptors were said to have been in the custody of Bloodlord Mandokir in Zul'Gurub.  This species of raptor has not been seen in many years."] = "Die einzigen bekannten Razzashi-Raptoren sollen in der Obhut von Blutfürst Mandokir in Zul'Gurub gewesen sein. Diese Raptorenart wurde seit vielen Jahren nicht mehr gesehen.",
    -- addon:data.mountdesc.60002:text
    ["The only reason for time is so that everything doesn't happen at once."] = "Die Zeit gibt es nur, damit nicht alles auf einmal passiert.",
    -- addon:data.petdesc.67527:text
    ["The onyx panther is invisible at night, like a stalking shadow, and disappears with the dawn."] = "Der Onyxpanther ist nachts unsichtbar wie ein pirschender Schatten und verschwindet mit der Morgendämmerung.",
    -- addon:data.mountdesc.39315:text
    ["The orcs once hunted these graceful herd animals as part of the om'riggor rite of passage ceremony."] = "Die Orcs jagten diese anmutigen Herdentiere einst im Rahmen der Initiationszeremonie des Om'riggor.",
    -- addon:data.petdesc.69541:text
    ["The pandaren monk is a fearless traveling companion, constantly training in his art... unless you offer him a drink. He considers it rude to refuse."] = "Der Pandarenmönch ist ein furchtloser Reisegefährte, der ständig seine Kunst übt... es sei denn, Ihr bietet ihm einen Trunk an. Eine Ablehnung hält er für unhöflich.",
    -- addon:data.petdesc.27570:text
    ["The power of love can be a dangerous thing, especially when wielded by an airborne, ill-tempered goblin."] = "Die Macht der Liebe kann gefährlich sein, besonders in den Händen eines fliegenden, übellaunigen Goblins.",
    -- addon:data.mountdesc.468:text
    ["The powerful and unyielding white stallion features heavily in the myths of ancient human tribes."] = "Der mächtige und unbeugsame weiße Hengst spielt in den Mythen der uralten Menschenstämme eine große Rolle.",
    -- addon:data.petdesc.61349:text
    ["The rare albino tickbird is revered amongst the Oracles. It is seen as a sign of heavy rainstorms, good grub harvests, and hibernating wolvar."] = "Der seltene Albino-Zeckenvogel wird von den Orakeln verehrt. Er gilt als Zeichen für schwere Regenfälle, gute Madenernten und winterschlafende Wolvar.",
    -- addon:data.mountdesc.41252:text
    ["The rest be forgotten to walk upon the ground, clipped wings and shame. -Word of the Raven"] = "Die Übrigen seien vergessen, auf dass sie auf dem Boden wandeln, mit gestutzten Flügeln und in Schande. - Wort des Raben",
    -- addon:trials.the_season_being_played:text
    ["The season being played."] = "Die laufende Saison.",
    -- addon:trials.the_season_mount_traded_for:text
    ["The season mount, traded for one Argent Laurel."] = "Das Reittier der Saison, eingetauscht gegen einen Argentumlorbeer.",
    -- addon:talents.the_server_did_not_answer:text
    ["The server did not answer: nothing was changed."] = "Der Server hat nicht geantwortet: Es wurde nichts geändert.",
    -- addon:data.petdesc.40614:text
    ["The sin'dorei use hawkstriders as mounts, but this little one was deemed unfit after being diagnosed with numerous anxiety disorders."] = "Die Sin'dorei nutzen Falkenschreiter als Reittiere, doch dieser Kleine wurde für untauglich befunden, nachdem man bei ihm zahlreiche Angststörungen festgestellt hatte.",
    -- addon:contracts.the_spirit_offers_contracts_on:text
    ["The spirit offers contracts on zones and dungeons a few levels above yours. Gain a level or two and come back."] = "Der Geist bietet Verträge für Gebiete und Dungeons an, die einige Stufen über Eurer liegen. Steigt eine oder zwei Stufen auf und kommt wieder.",
    -- addon:data.petdesc.62561:text
    ["The strand crawler has adapted to the northern cold by hibernating under the island beaches."] = "Der Strandkrabbler hat sich an die nördliche Kälte angepasst, indem er unter den Inselstränden Winterschlaf hält.",
    -- addon:data.mountdesc.59572:text
    ["The taunka use black polar bear pelts in their religious rites, usually at the funerals of those who hunt black polar bears."] = "Die Taunka verwenden schwarze Eisbärenfelle bei ihren religiösen Riten, meist bei den Begräbnissen derer, die schwarze Eisbären jagen.",
    -- addon:data.affix_text.the_third_mind_blast_on_the_same_target:text
    ["The third Mind Blast on the same target opens a Portal of Madness under it for 10 sec. A Crusher Tentacle and two Corruptor Tentacles rise and attack nearby enemies for @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power. Each tick of your Shadow Word: Pain makes them grow (Does not stack)"] = "Der dritte Gedankenschlag auf dasselbe Ziel öffnet 10 Sek. lang ein Portal des Wahnsinns unter ihm. Ein Schmettertentakel und zwei Verderbertentakel erheben sich und greifen Feinde in der Nähe mit @value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht an. Jeder periodische Schaden Eures Zaubers Schattenwort: Schmerz lässt sie wachsen (Nicht stapelbar)",
    -- addon:skillTree.the_tree_spends_the_soul:text
    ["The tree spends the |cffffd700Soul Ashes|r kept on your account. They arrive when you make an |cffffd700offering|r at a Spirit Healer, or when a run ends. This is what you have to spend; hover it to see what it buys."] = "Der Baum verbraucht die |cffffd700Seelenasche|r, die auf Eurem Account gespeichert ist. Ihr erhaltet sie, wenn Ihr bei einem Geistheiler eine |cffffd700Opfergabe|r darbringt oder wenn ein Durchlauf endet. Das ist es, was Ihr ausgeben könnt; bewegt den Mauszeiger darüber, um zu sehen, was Ihr dafür bekommt.",
    -- addon:data.petdesc.62513:text
    ["The volatile Durotar scorpion is a fierce desert predator. It's known for only occasionally stinging its owner."] = "Der launische Skorpion von Durotar ist ein wilder Wüstenräuber. Er ist dafür bekannt, seinen Besitzer nur gelegentlich zu stechen.",
    -- addon:data.mountdesc.59961:text
    ["The vrykul were the first to recognize their potential. Or maybe the second, depending on how you look at it."] = "Die Vrykul erkannten als Erste ihr Potenzial. Oder vielleicht als Zweite, je nachdem, wie man es betrachtet.",
    -- addon:data.mountdesc.23250:text
    ["The wolves of the Horde are befriended, not domesticated."] = "Die Wölfe der Horde werden nicht gezähmt, sondern zu Freunden gewonnen.",
    -- addon:data.mountdesc.35025:text
    ["Their plumage is more beautiful than any other. Subtlety is for the birds! I mean... other birds. -Viera Sunwhisper"] = "Ihr Gefieder ist schöner als jedes andere. Feingefühl ist etwas für die Vögel! Ich meine... andere Vögel. - Viera Sonnenwisper",
    -- addon:data.boss.theka_the_martyr:text
    ["Theka the Martyr"] = "Theka der Märtyrer",
    -- addon:data.affix_family.thekal_s_renewal:text
    ["Thekal's Renewal"] = "Thekals Erneuerung",
    -- addon:data.waystone.thelsamar_loch_modan:text
    ["Thelsamar, Loch Modan"] = "Thelsamar, Loch Modan",
    -- addon:data.waystone.theramore_isle_dustwallow_marsh:text
    ["Theramore Isle, Dustwallow Marsh"] = "Die Insel Theramore, Düstermarschen",
    -- addon:collections.gs_transmogrify_invalid_no_item:text
    ["There is no equipped item in this slot."] = "An diesem Platz ist kein Gegenstand angelegt.",
    -- addon:data.petdesc.15067:text
    ["These adorable critters love snuggling with their owners after a long day of brutal, bloody battle."] = "Diese bezaubernden Tierchen kuscheln sich nach einem langen Tag brutaler, blutiger Kämpfe liebend gern an ihre Besitzer.",
    -- addon:data.petdesc.26533:text
    ["These off-season allies work tirelessly to prepare for the Feast of Winter Veil, and would appreciate not being disturbed the rest of the year."] = "Diese Verbündeten der Nebensaison arbeiten unermüdlich an den Vorbereitungen für das Winterhauchfest und wären dankbar, das restliche Jahr über nicht gestört zu werden.",
    -- addon:data.petdesc.66175:text
    ["These possessed puppets are given a semblance of life by whimsical spirits of the departed."] = "Diese besessenen Puppen erhalten von launischen Geistern der Verstorbenen einen Anschein von Leben.",
    -- addon:data.mountdesc.64927:text
    ["These reanimated vessels of destruction do not fear death; they dispense it."] = "Diese wiederbelebten Gefäße der Zerstörung fürchten den Tod nicht; sie teilen ihn aus.",
    -- addon:options.these_settings_change_in_game:text
    ["These settings change in-game console variables (CVars). They persist between sessions."] = "Diese Einstellungen ändern Konsolenvariablen (CVars) des Spiels. Sie bleiben zwischen Sitzungen erhalten.",
    -- addon:data.petdesc.48406:text
    ["These stunning creatures, awarded to heroes for victory in battle, represent bravery and strength."] = "Diese prächtigen Geschöpfe, die Helden für Siege in der Schlacht verliehen werden, stehen für Tapferkeit und Stärke.",
    -- addon:data.petdesc.61350:text
    ["These voracious whelps grow at an incredible rate and can devour nearly twice their weight in raw meat per day."] = "Diese gefräßigen Welpen wachsen unglaublich schnell und können pro Tag fast das Doppelte ihres Gewichts an rohem Fleisch verschlingen.",
    -- addon:data.petdesc.62746:text
    ["These young orcs strive to embody the Argent Crusade's virtues: valor, strength, and integrity."] = "Diese jungen Orcs streben danach, die Tugenden des Argentumkreuzzugs zu verkörpern: Tapferkeit, Stärke und Integrität.",
    -- addon:data.mountdesc.61230:text
    ["They are not native to Northrend, but they have adapted extremely well to the cold. -Mei Francis"] = "Sie stammen nicht aus Nordend, haben sich aber äußerst gut an die Kälte angepasst. - Mei Francis",
    -- addon:data.mountdesc.32235:text
    ["They love lions in Stormwind, and the gryphon is half lion. Of course they might not like which half. -Gryphon Master Talonaxe"] = "In Sturmwind liebt man Löwen, und der Greif ist zur Hälfte ein Löwe. Ob ihnen die andere Hälfte gefällt, ist eine andere Frage. - Greifenmeister Krallenaxt",
    -- addon:data.affix_family.thick_hide:text
    ["Thick Hide"] = "Dickes Fell",
    -- addon:spec.third:text
    ["Third"] = "Dritte",
    -- addon:data.mountdesc.25953:text
    ["This (relatively) domesticated silithid is at home only in the desert sands of Ahn'Qiraj."] = "Dieser (verhältnismäßig) zahme Silithid ist nur im Wüstensand von Ahn'Qiraj zu Hause.",
    -- addon:callboard.this_week:text
    ["This Week"] = "Diese Woche",
    -- addon:collections.gs_transmogrify_tooltip_appearance_unusable:text
    ["This appearance can't be used by your character"] = "Diese Vorlage kann von Eurem Charakter nicht verwendet werden",
    -- addon:collections.gs_transmog_appearance_usable_holiday:text
    ["This appearance is only usable during holiday: %s."] = "Diese Vorlage ist nur während des Feiertags verwendbar: %s.",
    -- addon:playerRun.this_bar_is_your_contract:text
    ["This bar is your |cffffd700contract bonus|r, up to +400%. It only rises when you fulfil a |cffffd700Death contract|r: 50 creatures in a zone (+10%), every boss of a dungeon (+25%) or a raid (+125%). Dying loses the contracts in progress, never the bonus. |cffff4040Accepting death|r banks your ashes without the bonus, and the bonus is gone. Hover the bar any time to see all of this again."] = "Diese Leiste ist Euer |cffffd700Vertragsbonus|r, bis zu +400%. Sie steigt nur, wenn Ihr einen |cffffd700Todesvertrag|r erfüllt: 50 Kreaturen in einem Gebiet (+10%), alle Bosse eines Dungeons (+25%) oder eines Schlachtzugs (+125%). Beim Tod verliert Ihr die laufenden Verträge, nie aber den Bonus. |cffff4040Den Tod akzeptieren|r verbucht Eure Asche ohne den Bonus, und der Bonus ist verloren. Bewegt den Mauszeiger jederzeit über die Leiste, um all dies erneut zu sehen.",
    -- addon:data.mountdesc.459:text
    ["This breed of wolf prefers hunting in the fog, relying on its smoky hide to camouflage it from unsuspecting prey."] = "Diese Wolfsrasse jagt bevorzugt im Nebel und verlässt sich auf ihr rauchgraues Fell, um sich vor ahnungsloser Beute zu tarnen.",
    -- addon:perks.fail_invalid_upload:text
    ["This build contains no echoes usable by your class."] = "Dieser Aufbau enthält keine Echos, die Eure Klasse nutzen kann.",
    -- addon:talents.this_build_could_not_be:text
    ["This build could not be applied."] = "Diese Konfiguration konnte nicht angewendet werden.",
    -- addon:data.petdesc.35239:text
    ["This bunny is the cutest thing its opponent will ever see. It'll also be the last."] = "Dieses Häschen ist das Niedlichste, was sein Gegner je zu Gesicht bekommt. Und auch das Letzte.",
    -- addon:data.petdesc.26010:text
    ["This clever toy is equipped with a secret switch to disable its 'tranquil' mode. Luckily, even the engineers who built it don't know how to find it."] = "Dieses raffinierte Spielzeug hat einen geheimen Schalter, der seinen „friedlichen“ Modus abschaltet. Zum Glück wissen nicht einmal die Ingenieure, die es gebaut haben, wo er sich befindet.",
    -- addon:prestige.this_counter_shows_how_many:text
    ["This counter shows how many times you have prestiged. A prestige is a trade: you give up everything your Skill Tree was built on, and you keep one thing forever."] = "Dieser Zähler zeigt, wie oft Ihr bereits ein Prestige durchgeführt habt. Ein Prestige ist ein Handel: Ihr gebt alles auf, worauf Euer Aschebaum aufgebaut war, und behaltet eine Sache für immer.",
    -- addon:data.petdesc.67415:text
    ["This crafty raptor was born in the icy wastes of Northrend. Its harsh upbringing gives it strength when many others would perish."] = "Dieser listige Raptor wurde in den eisigen Einöden Nordends geboren. Seine harte Aufzucht verleiht ihm Kraft, wo viele andere umkommen würden.",
    -- addon:data.petdesc.28505:text
    ["This cub shares many traits with its relatives, but it's in a league of its own with its singing ability."] = "Dieses Junge hat viele Eigenschaften mit seinen Verwandten gemein, doch mit seinem Gesang spielt es in einer eigenen Liga.",
    -- addon:data.petdesc.10706:text
    ["This dark-feathered bird of prey is often seen as a harbinger of doom amongst the druids of Teldrassil."] = "Dieser dunkel gefiederte Raubvogel gilt unter den Druiden von Teldrassil oft als Vorbote des Unheils.",
    -- addon:dungeonFinder.this_difficulty_is_locked:text
    ["This difficulty is locked."] = "Dieser Schwierigkeitsgrad ist gesperrt.",
    -- addon:perks.tip_spec_belongs:text
    ["This echo belongs to the {spec} specialization."] = "Dieses Echo gehört zur Spezialisierung {spec}.",
    -- addon:journal.this_echo_will_not_appear:text
    ["This echo will not appear in your draws."] = "Dieses Echo erscheint nicht in Euren Ziehungen.",
    -- addon:data.petdesc.66096:text
    ["This extremely rare species of mana wyrm is prized for its unique coloration and even temperament."] = "Diese äußerst seltene Manawyrmart wird wegen ihrer einzigartigen Färbung und ihres ausgeglichenen Wesens geschätzt.",
    -- addon:data.mountdesc.60119:text
    ["This formidable mount is bought with the blood of Alliance leaders, but you would have killed them for free."] = "Dieses gewaltige Reittier wird mit dem Blut von Anführern der Allianz erkauft, aber Ihr hättet sie auch umsonst getötet.",
    -- addon:playerRun.this_frame_follows_your_run:text
    ["This frame follows your run: one life, from level 1 until you |cffff4040accept death|r. What you earn here is not safe yet. It reaches your account, and your |cffffd700Skill Tree|r, when you make an offering at a Spirit Healer or when the run ends."] = "Dieses Fenster begleitet Euren Durchlauf: ein Leben, von Stufe 1 an, bis Ihr |cffff4040„Den Tod akzeptieren“|r wählt. Was Ihr hier verdient, ist noch nicht sicher. Es geht auf Euer Konto und in Euren |cffffd700Aschebaum|r über, wenn Ihr bei einem Geistheiler eine Opfergabe darbringt oder wenn der Durchlauf endet.",
    -- addon:data.petdesc.45174:text
    ["This golden pig honors its ancestors by giving its allies good fortune."] = "Dieses goldene Schwein ehrt seine Ahnen, indem es seinen Verbündeten Glück bringt.",
    -- addon:data.petdesc.67417:text
    ["This hatchling is coveted for its unique coloration. Despite Breanni's loving care, the raptor's feral nature cannot be restrained."] = "Dieses Junge ist wegen seiner einzigartigen Färbung begehrt. Trotz Breannis liebevoller Pflege lässt sich die wilde Natur des Raptors nicht bändigen.",
    -- addon:data.mountdesc.8394:text
    ["This hearty mount's ferocious appetite earned it the nickname \"Dragon Belly\" in the night elf language."] = "Der unbändige Appetit dieses kräftigen Reittiers brachte ihm in der Sprache der Nachtelfen den Spitznamen „Drachenbauch“ ein.",
    -- addon:data.mountdesc.17459:text
    ["This historic piece of gnomish engineering was forced into retirement due to its extremely \"touchy\" gyroscometer."] = "Dieses historische Stück gnomischer Ingenieurskunst musste wegen seines äußerst „empfindlichen“ Gyroskometers in den Ruhestand gehen.",
    -- addon:torment.this_instance_runs_at_your:text
    ["This instance runs at {here} - your own Torment is {own}."] = "Diese Instanz läuft auf {here} - Eure eigene Qual ist {own}.",
    -- addon:data.petdesc.63712:text
    ["This is actually three pets in one. You won't know what you'll get until you summon it!"] = "Das sind eigentlich drei Haustiere in einem. Ihr wisst nicht, was Ihr bekommt, bis Ihr es beschwört!",
    -- addon:toolbelt.fail_locked:text
    ["This is not unlocked on this character. It is sold in the shop."] = "Dies ist auf diesem Charakter nicht freigeschaltet. Es wird im Shop verkauft.",
    -- addon:collections.gs_heirlooms_journal_tutorial_upgrade:text
    ["This is the max level of the heirloom. You can raise this level by using special upgrade tokens."] = "Dies ist die Höchststufe des Erbstücks. Ihr könnt diese Stufe mit besonderen Aufwertungsmarken erhöhen.",
    -- addon:journal.this_is_your_active_loadout:text
    ["This is your active loadout."] = "Dies ist Eure aktive Konfiguration.",
    -- addon:collections.gs_transmogrify_tooltip_appearance_uncollectable:text
    ["This item can't be used for transmogrification, but may be worn as equipment"] = "Dieser Gegenstand kann nicht für die Transmogrifikation verwendet, aber als Ausrüstung getragen werden",
    -- addon:collections.gs_transmogrify_invalid_destination:text
    ["This item cannot be transmogrified."] = "Dieser Gegenstand kann nicht transmogrifiziert werden.",
    -- addon:affixToast.this_item_carries_an_affix:text
    ["This item carries an affix. While you wear the item, you benefit from it, but looting it does |cffff8040not|r teach it to you."] = "Dieser Gegenstand trägt ein Affix. Solange Ihr ihn angelegt habt, profitiert Ihr davon, doch durch das Plündern erlernt Ihr es |cffff8040nicht|r.",
    -- addon:extraction.tip_no_affix:text
    ["This item carries no affix."] = "Dieser Gegenstand trägt kein Affix.",
    -- addon:collections.gs_transmogrify_invalid_not_soulbound:text
    ["This item is not soulbound."] = "Dieser Gegenstand ist nicht seelengebunden.",
    -- addon:extraction.this_item_takes_no_affix:text
    ["This item takes no affix"] = "Dieser Gegenstand nimmt kein Affix auf",
    -- addon:collections.gs_transmogrify_invalid_mismatch:text
    ["This item type isn't compatible with this appearance."] = "Diese Gegenstandsart ist mit dieser Vorlage nicht kompatibel.",
    -- addon:data.petdesc.28871:text
    ["This little piece of summer smells of warm evenings and lightning storms. If you look closely, you might be able to make out a face."] = "Dieses kleine Stück Sommer duftet nach warmen Abenden und Gewittern. Wenn Ihr genau hinseht, könnt Ihr vielleicht ein Gesicht erkennen.",
    -- addon:perks.fail_locked:text
    ["This loadout slot is locked - unlock it with gold first."] = "Dieser Konfigurationsplatz ist gesperrt - schaltet ihn zuerst mit Gold frei.",
    -- addon:data.petdesc.54187:text
    ["This mechanical warrior is a favorite gift during Winter Veil. Batteries not included, but rockets definitely are!"] = "Dieser mechanische Krieger ist ein beliebtes Geschenk zum Winterhauchfest. Batterien nicht enthalten, Raketen aber auf jeden Fall!",
    -- addon:journal.this_menu_manages_your_builds:text
    ["This menu manages your builds. |cff60a0e0Loadouts|r are independent echo builds, each with its own echoes, locked echoes, banishes, rerolls and freezes. Switch between them at any level: the one you arrive on is handed every draw your level owes it. Death empties them all, locked echoes excepted.\n\n|cffa080e0Wishlists|r are for |cffffd700designing|r: the echoes you wish to collect, assembled into your dream build. Create one with |cffffd700New Wishlist|r, pick its echoes in the catalog, then |cffffd700Done|r. While it is active, its echoes are highlighted in your draws to guide you toward it."] = "Dieses Menü verwaltet Eure Aufbauten. |cff60a0e0Konfigurationen|r sind unabhängige Echo-Aufbauten mit jeweils eigenen Echos, gesicherten Echos, Verbannungen, Neuwürfen und Einfrierungen. Ihr könnt auf jeder Stufe zwischen ihnen wechseln: Die Konfiguration, zu der Ihr wechselt, erhält jede Ziehung, die Eure Stufe ihr schuldet. Der Tod leert sie alle, gesicherte Echos ausgenommen.\n\n|cffa080e0Wunschlisten|r dienen dem |cffffd700Planen|r: die Echos, die Ihr sammeln wollt, zusammengestellt zu Eurem Traumaufbau. Erstellt eine mit |cffffd700Neue Wunschliste|r, wählt ihre Echos im Katalog aus und klickt dann auf |cffffd700Fertig|r. Solange sie aktiv ist, werden ihre Echos in Euren Ziehungen hervorgehoben, um Euch zu ihr zu führen.",
    -- addon:data.petdesc.42609:text
    ["This mischievous gourd likes to pop out of the ground and scare you right out of your pants. Hail to the pumpkin song!"] = "Dieser schelmische Kürbis springt gern aus dem Boden und jagt Euch einen Schrecken ein, dass Euch die Hose rutscht. Ein Hoch auf das Kürbislied!",
    -- addon:data.petdesc.67416:text
    ["This offspring of Takk the Leaper is incredibly agile and can maneuver through difficult environments with ease."] = "Dieser Nachkomme von Takk dem Springer ist unglaublich wendig und bewältigt schwieriges Gelände mühelos.",
    -- addon:data.petdesc.17707:text
    ["This pint-sized panda cub is highly sought after by adventurers around Azeroth - despite its narcoleptic nature."] = "Dieses winzige Pandajunge ist bei Abenteurern in ganz Azeroth heiß begehrt - trotz seiner Neigung zur Schlafsucht.",
    -- addon:data.mountdesc.63635:text
    ["This raptor breed was originally cultivated by the Drakkari, but has since been adopted by the Darkspear tribe in Northrend."] = "Diese Raptorenrasse wurde ursprünglich von den Drakkari gezüchtet, ist aber inzwischen vom Dunkelspeerstamm in Nordend übernommen worden.",
    -- addon:data.petdesc.61855:text
    ["This rare bear is bred for its small size and perpetually youthful appearance."] = "Dieser seltene Bär wird wegen seiner geringen Größe und seines ewig jugendlichen Aussehens gezüchtet.",
    -- addon:collections.gs_transmog_set_limited_time_set_tooltip:text
    ["This set can be collected during the current season only."] = "Dieses Set kann nur während der aktuellen Saison gesammelt werden.",
    -- addon:perks.fail_empty:text
    ["This slot is empty."] = "Dieser Platz ist leer.",
    -- addon:data.petdesc.15049:text
    ["This tiny peacekeeper security bot is often outfitted with the latest arcane nullifiers and crowd pummelers. Not for the environmentally minded."] = "Dieser winzige Friedenswahrer-Sicherheitsroboter ist oft mit den neuesten arkanen Nullifikatoren und Massenprüglern ausgestattet. Nichts für Umweltbewusste.",
    -- addon:collections.gs_transmogrify_invalid_item_type:text
    ["This type of item cannot be transmogrified."] = "Diese Gegenstandsart kann nicht transmogrifiziert werden.",
    -- addon:data.mountdesc.60114:text
    ["This ursine mount's swiftness is enhanced by its heavy armor, imbued with magic from Kirin Tor magi."] = "Die Schnelligkeit dieses Bärenreittiers wird durch seine schwere Rüstung verstärkt, die von den Magiern der Kirin Tor mit Magie erfüllt wurde.",
    -- addon:callboard.this_week_2:text
    ["This week"] = "Diese Woche",
    -- addon:data.mountdesc.59793:text
    ["This wild variant of the mammoth is not bred for riding. Most wooly mammoths are captured in the wild and tamed by their riders, resulting in a fierce, cunning mount."] = "Diese wilde Mammutvariante wird nicht für das Reiten gezüchtet. Die meisten Wollmammuts werden in der Wildnis gefangen und von ihren Reitern gezähmt, was ein wildes, listiges Reittier hervorbringt.",
    -- addon:prestige.this_will_erase:text
    ["This will ERASE"] = "Folgendes wird GELÖSCHT",
    -- addon:data.petdesc.71840:text
    ["This, um, 'adorable' little guy likes to play with critters. Just don't let them get too close."] = "Dieser, äh, „bezaubernde“ kleine Kerl spielt gern mit Kleintieren. Lasst sie ihm nur nicht zu nahe kommen.",
    -- addon:data.waystone.thondoril_river_western_plaguelands:text
    ["Thondoril River, Western Plaguelands"] = "Fluss Thondoril, Westliche Pestländer",
    -- addon:data.petdesc.69536:text
