    ["Waystones, Bank, Guild Bank, Mailbox, Auction House, Call Board, Affix-Anvil, Forge, Vendor and Scavenger's Eye."] = "Wegsteine, Bank, Gildenbank, Briefkasten, Auktionshaus, Brett des Heldenrufs, Affix-Amboss, Schmiede, Händler und Auge des Plünderers.",
    -- addon:data.mountdesc.23222:text
