    -- addon:toolbelt.hdr_picked_up:text
    ["What Gets Picked Up"] = "Was aufgehoben wird",
    -- addon:toolbelt.hdr_what_sold:text
    ["What Gets Sold"] = "Was verkauft wird",
    -- addon:data.mountdesc.65639:text
    ["What do you mean is it dyed? Oh, the bird. We did touch up the red just a little. -Trellis Morningsun"] = "Was soll das heißen, ob er gefärbt ist? Ach, der Vogel. Das Rot haben wir nur ein klein wenig aufgefrischt. -Trellis Morgensonne",
    -- addon:prestige.what_it_costs:text
    ["What it costs"] = "Was es kostet",
    -- addon:data.mountdesc.46199:text
    ["What it lacks in safety features it more than makes up for in speed and style.  Not for the faint of heart."] = "Was ihr an Sicherheitsvorkehrungen fehlt, macht sie durch Geschwindigkeit und Stil mehr als wett. Nichts für schwache Nerven.",
    -- addon:prestige.what_it_pays:text
    ["What it pays"] = "Was es einbringt",
    -- addon:prestige.what_you_keep:text
    ["What you keep"] = "Was Ihr behaltet",
    -- addon:contracts.what_your_run_is_worth:text
    ["What your run is worth"] = "Was Euer Durchlauf wert ist",
    -- addon:data.mountdesc.17481:text
    ["When Baron Rivendare became a champion of the Scourge, he condemned his favorite horse to join him in undeath."] = "Als Baron Totenschwur zum Streiter der Geißel wurde, verdammte er sein Lieblingspferd dazu, sich ihm im Untod anzuschließen.",
    -- addon:data.affix_text.when_black_arrow_ends_3_spiderlings_hatc:text
    ["When Black Arrow ends, 3 spiderlings hatch from the target and attack nearby enemies for 10 sec, each dealing @value@50%@value@ @range@[10%-50%]@range@ of your Attack Power every second (Does not stack)"] = "Endet Schwarzer Pfeil, schlüpfen 3 Spinnlinge aus dem Ziel und greifen 10 Sek. lang Feinde in der Nähe an. Jeder verursacht jede Sekunde Schaden in Höhe von @value@50%@value@ @range@[10%-50%]@range@ Eurer Angriffskraft (Nicht stapelbar)",
    -- addon:data.affix_text.when_deterrence_ends_a_carapace_absorbs:text
    ["When Deterrence ends, a carapace absorbs @value@600%@value@ @range@[120%-600%]@range@ of your Attack Power for 10 sec, and enemies that strike it are webbed for 2 sec (Does not stack)"] = "Endet Abschreckung, absorbiert ein Panzer 10 Sek. lang Schaden in Höhe von @value@600%@value@ @range@[120%-600%]@range@ Eurer Angriffskraft, und Feinde, die ihn treffen, werden 2 Sek. lang eingesponnen (Nicht stapelbar)",
    -- addon:data.affix_text.when_divine_shield_ends_it_bursts_into_l:text
    ["When Divine Shield ends, it bursts into light: you and allies within 15 yd are healed for @value@1500%@value@ @range@[300%-1500%]@range@ of your Spell Power (Does not stack)"] = "Wenn Gottesschild endet, birst er in Licht: Ihr und Verbündete in einem Umkreis von 15 Metern werdet um @value@1500%@value@ @range@[300%-1500%]@range@ Eurer Zaubermacht geheilt (Nicht stapelbar)",
    -- addon:data.affix_text.when_guardian_spirit_saves_an_ally_you_a:text
    ["When Guardian Spirit saves an ally, you are healed for @value@30%@value@ @range@[10%-30%]@range@ of your health as well (Does not stack)"] = "Wenn Schutzgeist einen Verbündeten rettet, werdet auch Ihr um @value@30%@value@ @range@[10%-30%]@range@ Eurer Gesundheit geheilt (Nicht stapelbar)",
    -- addon:data.affix_text.when_haunt_returns_to_you_it_refreshes_y:text
    ["When Haunt returns to you, it refreshes your Corruption on the target and reduces the cooldown of Haunt by @value@3@value@ @range@[1-3]@range@ sec (Does not stack)"] = "Wenn Heimsuchung zu Euch zurückkehrt, erneuert sie Eure Verderbnis auf dem Ziel und verringert die Abklingzeit von Heimsuchung um @value@3@value@ @range@[1-3]@range@ Sek. (Nicht stapelbar)",
    -- addon:data.affix_text.when_haunt_returns_to_you_it_stays_as_a:text
    ["When Haunt returns to you, it stays as a soul fragment orbiting you for 20 sec, up to 4. Each fragment deals @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power as Shadow damage to enemies it passes (Does not stack)"] = "Wenn Heimsuchung zu Euch zurückkehrt, bleibt sie 20 Sek. lang als Seelenfragment bestehen, das Euch umkreist (bis zu 4 gleichzeitig). Jedes Fragment verursacht Schattenschaden in Höhe von @value@50%@value@ @range@[10%-50%]@range@ Eurer Zaubermacht an Feinden, an denen es vorbeizieht (Nicht stapelbar)",
    -- addon:data.affix_text.when_ice_block_ends_it_shatters_into_a_f:text
    ["When Ice Block ends, it shatters into a frost barrier absorbing @value@600%@value@ @range@[120%-600%]@range@ of your Spell Power for 10 sec (Does not stack)"] = "Wenn Eisblock endet, zerspringt er zu einer Frostbarriere, die 10 Sek. lang @value@600%@value@ @range@[120%-600%]@range@ Eurer Zaubermacht absorbiert (Nicht stapelbar)",
    -- addon:data.affix_text.when_lifebloom_blooms_it_opens_a_dream_p:text
    ["When Lifebloom blooms, it opens a Dream Portal at the ally for 6 sec. Allies near the portal are healed for @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power every second (Does not stack)"] = "Wenn Blühendes Leben aufblüht, öffnet es 6 Sek. lang ein Traumportal beim Verbündeten. Verbündete in der Nähe des Portals werden jede Sekunde um @value@50%@value@ @range@[10%-50%]@range@ Eurer Zaubermacht geheilt (Nicht stapelbar)",
    -- addon:data.affix_text.when_living_bomb_explodes_it_plants_a_ne:text
    ["When Living Bomb explodes, it plants a new Living Bomb on one enemy it hits, up to 3 times in a row. Each new bomb deals @value@80%@value@ @range@[40%-80%]@range@ of the damage (Does not stack)"] = "Wenn Lebende Bombe explodiert, pflanzt sie eine neue Lebende Bombe auf einen getroffenen Feind, bis zu 3-mal hintereinander. Jede neue Bombe verursacht @value@80%@value@ @range@[40%-80%]@range@ des Schadens (Nicht stapelbar)",
    -- addon:data.affix_text.when_rake_ends_it_gives_you_value_10_val:text
    ["When Rake ends, it gives you @value@10@value@ @range@[10-30]@range@ energy or rage (Does not stack)"] = "Wenn Krallenhieb endet, erhaltet Ihr @value@10@value@ @range@[10-30]@range@ Energie oder Wut (Nicht stapelbar)",
    -- addon:data.affix_text.when_rake_ends_it_gives_you_value_16_val:text
    ["When Rake ends, it gives you @value@16@value@ @range@[10-30]@range@ energy or rage (Does not stack)"] = "Wenn Krallenhieb endet, erhaltet Ihr @value@16@value@ @range@[10-30]@range@ Energie oder Wut (Nicht stapelbar)",
    -- addon:data.affix_text.when_rake_ends_it_gives_you_value_20_val:text
    ["When Rake ends, it gives you @value@20@value@ @range@[10-30]@range@ energy or rage (Does not stack)"] = "Wenn Krallenhieb endet, erhaltet Ihr @value@20@value@ @range@[10-30]@range@ Energie oder Wut (Nicht stapelbar)",
    -- addon:data.affix_text.when_rake_ends_it_gives_you_value_24_val:text
    ["When Rake ends, it gives you @value@24@value@ @range@[10-30]@range@ energy or rage (Does not stack)"] = "Wenn Krallenhieb endet, erhaltet Ihr @value@24@value@ @range@[10-30]@range@ Energie oder Wut (Nicht stapelbar)",
    -- addon:data.affix_text.when_rake_ends_it_gives_you_value_30_val:text
    ["When Rake ends, it gives you @value@30@value@ @range@[10-30]@range@ energy or rage (Does not stack)"] = "Wenn Krallenhieb endet, erhaltet Ihr @value@30@value@ @range@[10-30]@range@ Energie oder Wut (Nicht stapelbar)",
    -- addon:data.affix_text.when_a_power_word_shield_of_yours_is_ful:text
    ["When a Power Word: Shield of yours is fully consumed, the remaining cooldown of Penance is reduced by @value@3@value@ @range@[1-3]@range@ sec (Does not stack)"] = "Wird ein von Euch gewirktes Machtwort: Schild vollständig aufgebraucht, verringert sich die verbleibende Abklingzeit von Sühne um @value@3@value@ @range@[1-3]@range@ Sek. (Nicht stapelbar)",
    -- addon:data.mountdesc.63637:text
    ["When a night elf's mount perishes, it is custom for the rider to keep one of the saber's great fangs as a token of remembrance."] = "Wenn das Reittier eines Nachtelfen stirbt, ist es Brauch, dass der Reiter einen der großen Fangzähne des Säblers als Andenken behält.",
    -- addon:options.when_enabled_the_camera_can:text
    ["When enabled, the camera can move freely through certain world objects rather than being blocked by them."] = "Wenn aktiviert, kann sich die Kamera frei durch bestimmte Weltobjekte bewegen, statt von ihnen blockiert zu werden.",
    -- addon:data.mountdesc.17465:text
    ["When fallen heroes are raised into undeath, so too are their horses."] = "Wenn gefallene Helden zum Untod erweckt werden, geschieht dasselbe mit ihren Pferden.",
    -- addon:data.petdesc.53316:text
    ["When it senses the impending death of a nearby creature, the skull will emit an ear-piercing cackle."] = "Wenn er den nahenden Tod einer Kreatur in der Nähe spürt, stößt der Schädel ein ohrenbetäubendes Gackern aus.",
    -- addon:data.petdesc.45125:text
    ["When the Burning Legion invaded Outland, Landro Longshot contributed this design to the war effort. Both the Alliance and Horde passed on production."] = "Als die Brennende Legion in die Scherbenwelt einfiel, steuerte Landro Fernblick diesen Entwurf zu den Kriegsanstrengungen bei. Sowohl die Allianz als auch die Horde lehnten die Produktion ab.",
    -- addon:prestige.when_to_do_it:text
    ["When to do it"] = "Wann Ihr es tun solltet",
    -- addon:data.mountdesc.63638:text
    ["When you absolutely, positively have to be there right now. -Rillie Spindlenut"] = "Wenn Ihr unbedingt, absolut und sofort dort sein müsst. - Rillie Spindelnuss",
    -- addon:data.affix_text.when_you_fall_below_35_health_you_unleas:text
    ["When you fall below 35% health, you unleash a shockwave dealing @value@200%@value@ @range@[40%-200%]@range@ of your Attack Power or Spell Power as Physical damage to enemies within 8 yards and stunning them for 2 sec (once every 45 sec) (Does not stack)"] = "Wenn Eure Gesundheit unter 35% fällt, entfesselt Ihr eine Schockwelle, die körperlichen Schaden in Höhe von @value@200%@value@ @range@[40%-200%]@range@ Eurer Angriffskraft oder Zaubermacht an Feinden in einem Umkreis von 8 Metern verursacht und sie 2 Sek. lang betäubt (einmal alle 45 Sek.) (Nicht stapelbar)",
    -- addon:data.affix_text.when_you_fall_below_40_health_you_are_he:text
    ["When you fall below 40% health, you are healed for 20% of your maximum health; cannot occur more than once every @value@40 sec@value@ @range@[120 sec-40 sec]@range@ (Does not stack)"] = "Sinkt Eure Gesundheit unter 40%, werdet Ihr um 20% Eurer maximalen Gesundheit geheilt; kann höchstens einmal alle @value@40 sec@value@ @range@[120 sec-40 sec]@range@ auftreten (Nicht stapelbar)",
    -- addon:data.affix_text.when_your_chains_of_ice_end_the_frost_bu:text
    ["When your Chains of Ice end, the frost bursts out: the target and non-boss enemies within 8 yd are frozen in place for @value@3@value@ @range@[1-3]@range@ sec (Does not stack)"] = "Wenn Eure Eisketten enden, bricht der Frost hervor: Das Ziel und Feinde außer Bossen in einem Umkreis von 8 Metern werden @value@3@value@ @range@[1-3]@range@ Sek. lang festgefroren (Nicht stapelbar)",
    -- addon:data.affix_text.when_your_rejuvenation_expires_or_jumps:text
    ["When your Rejuvenation expires or jumps to another ally, it leaves an Emerald flower for 6 sec that heals allies within 5 yd for @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power every second (Does not stack)"] = "Wenn Eure Verjüngung ausläuft oder auf einen anderen Verbündeten überspringt, hinterlässt sie 6 Sek. lang eine Smaragdblume, die Verbündete in einem Umkreis von 5 Metern jede Sekunde um @value@50%@value@ @range@[10%-50%]@range@ Eurer Zaubermacht heilt (Nicht stapelbar)",
    -- addon:data.mountdesc.58983:text
    ["Whenever you ride this mount, you feel the urge to shout, \"Cry havoc and let slip the murlocs of war!\""] = "Immer wenn Ihr dieses Reittier reitet, verspürt Ihr den Drang zu rufen: „Ruft Verderben und lasst die Murlocs des Krieges los!“",
    -- addon:data.affix_text.while_bestial_wrath_is_active_each_kill:text
    ["While Bestial Wrath is active, each Kill Command reduces the cooldown of Bestial Wrath by @value@8@value@ @range@[3-8]@range@ sec (Does not stack)"] = "Solange Zorn des Wildtiers aktiv ist, verringert jedes „Fass!“ die Abklingzeit von Zorn des Wildtiers um @value@8@value@ @range@[3-8]@range@ Sek. (Nicht stapelbar)",
    -- addon:data.affix_text.while_blade_flurry_is_active_your_hits_d:text
    ["While Blade Flurry is active, your hits daze enemies: they deal @value@30%@value@ @range@[6%-30%]@range@ less damage for 4 sec (Does not stack)"] = "Solange Klingenwirbel aktiv ist, machen Eure Treffer Feinde benommen: Sie verursachen 4 Sek. lang @value@30%@value@ @range@[6%-30%]@range@ weniger Schaden (Nicht stapelbar)",
    -- addon:data.affix_text.while_dispersion_is_active_a_barrier_gro:text
    ["While Dispersion is active, a barrier grows on you: it absorbs @value@600%@value@ @range@[120%-600%]@range@ of your Spell Power for 10 sec after Dispersion ends (Does not stack)"] = "Solange Dispersion aktiv ist, wächst eine Barriere um Euch: Sie absorbiert nach dem Ende von Dispersion 10 Sek. lang @value@600%@value@ @range@[120%-600%]@range@ Eurer Zaubermacht (Nicht stapelbar)",
    -- addon:data.affix_text.while_evasion_is_active_each_dodge_heals:text
    ["While Evasion is active, each dodge heals you for @value@6%@value@ @range@[2%-6%]@range@ of your health (Does not stack)"] = "Solange Entrinnen aktiv ist, heilt Euch jedes Ausweichen um @value@6%@value@ @range@[2%-6%]@range@ Eurer Gesundheit (Nicht stapelbar)",
    -- addon:data.affix_text.while_holy_shield_is_active_you_take_val:text
    ["While Holy Shield is active, you take @value@15%@value@ @range@[3%-15%]@range@ less spell damage and each block heals you for 0,5 % of your health (Does not stack)"] = "Solange Heiliger Schild aktiv ist, erleidet Ihr @value@15%@value@ @range@[3%-15%]@range@ weniger Zauberschaden, und jeder Block heilt Euch um 0,5% Eurer Gesundheit (Nicht stapelbar)",
    -- addon:data.affix_text.while_below_35_health_absorbs_value_12_v:text
    ["While below 35% health, absorbs @value@12%@value@ @range@[5%-25%]@range@ of damage taken (Does not stack)"] = "Absorbiert @value@12%@value@ @range@[5%-25%]@range@ des erlittenen Schadens, solange Eure Gesundheit unter 35% liegt (Nicht stapelbar)",
    -- addon:data.affix_text.while_below_35_health_absorbs_value_17_v:text
    ["While below 35% health, absorbs @value@17%@value@ @range@[5%-25%]@range@ of damage taken (Does not stack)"] = "Absorbiert @value@17%@value@ @range@[5%-25%]@range@ des erlittenen Schadens, solange Eure Gesundheit unter 35% liegt (Nicht stapelbar)",
    -- addon:data.affix_text.while_below_35_health_absorbs_value_25_v:text
    ["While below 35% health, absorbs @value@25%@value@ @range@[5%-25%]@range@ of damage taken (Does not stack)"] = "Absorbiert @value@25%@value@ @range@[5%-25%]@range@ des erlittenen Schadens, solange Eure Gesundheit unter 35% liegt (Nicht stapelbar)",
    -- addon:data.affix_text.while_below_35_health_absorbs_value_5_va:text
    ["While below 35% health, absorbs @value@5%@value@ @range@[5%-25%]@range@ of damage taken (Does not stack)"] = "Absorbiert @value@5%@value@ @range@[5%-25%]@range@ des erlittenen Schadens, solange Eure Gesundheit unter 35% liegt (Nicht stapelbar)",
    -- addon:data.affix_text.while_below_35_health_absorbs_value_8_va:text
    ["While below 35% health, absorbs @value@8%@value@ @range@[5%-25%]@range@ of damage taken (Does not stack)"] = "Absorbiert @value@8%@value@ @range@[5%-25%]@range@ des erlittenen Schadens, solange Eure Gesundheit unter 35% liegt (Nicht stapelbar)",
    -- addon:data.petdesc.74932:text
    ["While not nearly as destructive as its original master, the Ice Lord Ahune, the frostling has been known to lob chilly snowballs at unsuspecting adventurers."] = "Der Frostling ist zwar längst nicht so zerstörerisch wie sein ursprünglicher Meister, der Eisfürst Ahune, wirft aber bekanntermaßen eisige Schneebälle auf ahnungslose Abenteurer.",
    -- addon:data.affix_family.whirling_slash:text
    ["Whirling Slash"] = "Wirbelndes Schlitzen",
    -- addon:data.affix_text.whirlwind_also_hurls_a_spinning_blade_th:text
    ["Whirlwind also hurls a spinning blade that hits up to 3 more enemies within 15 yd for @value@75%@value@ @range@[30%-75%]@range@ of its damage (Does not stack)"] = "Wirbelwind schleudert zudem eine wirbelnde Klinge, die bis zu 3 weitere Feinde in einem Umkreis von 15 Metern mit @value@75%@value@ @range@[30%-75%]@range@ seines Schadens trifft (Nicht stapelbar)",
    -- addon:data.affix_family.whispered_ward:text
    ["Whispered Ward"] = "Geflüsterter Schutz",
    -- addon:data.affix_text.wild_growth_leaves_sunwell_light_on_ever:text
    ["Wild Growth leaves Sunwell light on every ally it heals: when it fades, it heals them for @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power (Does not stack)"] = "Wildwuchs hinterlässt auf jedem geheilten Verbündeten das Licht des Sonnenbrunnens: Wenn es verblasst, heilt es ihn um @value@150%@value@ @range@[30%-150%]@range@ Eurer Zaubermacht (Nicht stapelbar)",
    -- addon:data.petdesc.45082:text
    ["Wild sporebats are vicious creatures, but if tamed at a young age, they can be loyal companions."] = "Wilde Sporensegler sind bösartige Geschöpfe, doch wenn man sie jung zähmt, werden sie zu treuen Begleitern.",
    -- addon:data.mountdesc.63636:text
    ["Wildhammer Fact Checker claims that this specific breed was the first type of ram domesticated by the dwarves when they settled in Dun Morogh."] = "Der Tatsachenprüfer der Wildhämmer behauptet, diese spezielle Rasse sei die erste Widderart gewesen, die die Zwerge domestizierten, als sie sich in Dun Morogh niederließen.",
