    -- addon:instanceTracker.you_already_cleared_this_raid:text
    ["You already cleared this raid this week. Its Soul Shards come back after the weekly reset (Tuesday 03:00 UTC)."] = "Ihr habt diesen Schlachtzug diese Woche bereits abgeschlossen. Seine Seelensplitter kehren nach dem wöchentlichen Zurücksetzen (Dienstag, 03:00 UTC) zurück.",
    -- addon:collections.gs_transmog_outfit_confirm_overwrite:text
    ["You already have an oufit named %s. Would you like to overwrite it?"] = "Ihr habt bereits ein Outfit namens %s. Wollt Ihr es überschreiben?",
    -- addon:contracts.you_already_hold_a_contract:text
    ["You already hold a contract: fulfil or cancel it first"] = "Ihr habt bereits einen Vertrag: Erfüllt ihn zuerst oder brecht ihn ab",
    -- addon:callboard.you_already_hold_that_contract:text
    ["You already hold that contract."] = "Diesen Vertrag habt Ihr bereits angenommen.",
    -- addon:skillTree.you_already_own_this_node:text
    ["You already own this node."] = "Ihr besitzt diesen Knoten bereits.",
    -- addon:skillTree.you_are_about_to_spend:text
    ["You are about to spend Soul Ashes on your Skill Tree.\n\nThis is |cffFF0000final|r: once applied, a rank can never be unlearned and its Soul Ashes are never refunded. Only a |cffFF4444Prestige|r resets the tree, and the octagon-framed nodes survive even that."] = "Ihr seid im Begriff, Seelenasche für Euren Aschebaum auszugeben.\n\nDies ist |cffFF0000endgültig|r: Ein einmal angewandter Rang kann nie wieder verlernt werden, und seine Seelenasche wird nie erstattet. Nur ein |cffFF4444Prestige|r setzt den Baum zurück, und die achteckig umrahmten Knoten überstehen sogar das.",
    -- addon:perks.fail_same:text
    ["You are already playing this loadout."] = "Ihr spielt diese Konfiguration bereits.",
    -- addon:toolbelt.fail_goldcap:text
    ["You are carrying too much gold to sell anything."] = "Ihr tragt zu viel Gold bei Euch, um etwas zu verkaufen.",
    -- addon:perks.popup_spec_text:text
    ["You are choosing your |cffffd100echo specialization|r.\n\nPick |cffffd100%s|r with |cffffd100%s|r?\n\nThen, every 10 levels, you will be offered three echoes of this specialization. Your talents are not changed.\n\nThis cannot be changed until you accept death."] = "Ihr wählt Eure |cffffd100Echo-Spezialisierung|r.\n\n|cffffd100%s|r mit |cffffd100%s|r wählen?\n\nDanach werden Euch alle 10 Stufen drei Echos dieser Spezialisierung angeboten. Eure Talente bleiben unverändert.\n\nDies lässt sich erst ändern, wenn Ihr „Den Tod akzeptieren“ wählt.",
    -- addon:death.title
    ["You are dead"] = "Ihr seid tot",
    -- addon:trials.you_are_down:text
    ["You are down"] = "Ihr seid niedergestreckt",
    -- addon:callboard.you_are_here:text
    ["You are here"] = "Ihr seid hier",
    -- addon:toolbelt.fail_noguild:text
    ["You are not in a guild."] = "Ihr seid in keiner Gilde.",
    -- addon:core.you_are_now_spectating:text
    ["You are now spectating."] = "Ihr seid jetzt Zuschauer.",
    -- addon:contracts.you_are_past_its_level:text
    ["You are past its level: nothing counts any more"] = "Ihr habt seine Stufe überschritten: Nichts zählt mehr",
    -- addon:worldChannel.you_can_always_join_later:text
    ["You can always join later with /join <channel> (e.g. /join world)"] = "Ihr könnt jederzeit später mit /join <Kanal> beitreten (z. B. /join world)",
    -- addon:collections.gs_transmog_specs_button_tutorial:text
    ["You can apply this look to all your specializations, or just your current one."] = "Ihr könnt dieses Aussehen auf alle Eure Spezialisierungen anwenden oder nur auf die aktuelle.",
    -- addon:playerRun.you_can_come_back_by:text
    ["You can come back by paying part of your run: the first resurrection costs |cffffd70025%|r of its Soul Ashes and Shards, |cffff4040each next one 25% more|r. Another player can also resurrect you, once per run. The number is how many you paid this run. |cffff4040Accepting death|r ends the run."] = "Ihr könnt zurückkehren, indem Ihr einen Teil Eures Durchlaufs bezahlt: Die erste Wiederbelebung kostet |cffffd70025%|r seiner Seelenasche und Seelensplitter, |cffff4040jede weitere 25% mehr|r. Ein anderer Spieler kann Euch außerdem einmal pro Durchlauf wiederbeleben. Die Zahl zeigt, wie viele Ihr in diesem Durchlauf bezahlt habt. |cffff4040Den Tod akzeptieren|r beendet den Durchlauf.",
    -- addon:callboard.you_can_hold_up_to_5_of_each:text
    ["You can hold up to 5 of each."] = "Ihr könnt von jedem bis zu 5 besitzen.",
    -- addon:collections.gs_err_no_riding_skill:text
    ["You can learn riding and obtain a mount from your riding trainer at level 20"] = "Ihr könnt auf Stufe 20 bei Eurem Reitlehrer Reiten erlernen und ein Reittier erhalten",
    -- addon:dungeonFinder.you_can_now_join_dungeons_click_here_to:text
    ["You can now join dungeons! Click here to open the Dungeon Finder."] = "Ihr könnt jetzt Dungeons beitreten! Klickt hier, um den Dungeonbrowser zu öffnen.",
    -- addon:dungeonFinder.you_can_now_join_dungeons_click_this_but:text
    ["You can now join dungeons! Click this button to open the Dungeon Finder."] = "Ihr könnt jetzt Dungeons beitreten! Klickt auf diesen Knopf, um den Dungeonbrowser zu öffnen.",
    -- addon:callboard.you_can_only_change_your_starting_zone_i:text
    ["You can only change your starting zone inside a starting zone."] = "Ihr könnt Euer Startgebiet nur innerhalb eines Startgebiets ändern.",
    -- addon:callboard.you_can_only_change_your_starting_zone_w:text
    ["You can only change your starting zone while you are in a starting zone."] = "Ihr könnt Euer Startgebiet nur ändern, solange Ihr Euch in einem Startgebiet befindet.",
    -- addon:extBank.you_can_only_place_a:text
    ["You can only place a bag here from your inventory."] = "Ihr könnt hier nur eine Tasche aus Eurem Inventar ablegen.",
