    -- addon:data.mountdesc.49378:text
    ["You can't remember exactly how you got this mount. Then again, you can't remember much of anything that happens at Brewfest."] = "Ihr könnt Euch nicht genau erinnern, wie Ihr an dieses Reittier gekommen seid. Andererseits könnt Ihr Euch an kaum etwas erinnern, was beim Braufest passiert.",
    -- addon:collections.gs_transmog_outfit_all_invalid_appearances:text
