    -- addon:trials.you_fell:text
    ["You fell."] = "Ihr seid gefallen.",
    -- addon:contracts.you_fulfilled_every_contract_the:text
    ["You fulfilled every contract the spirit offers you on this run. Gain a level and new ones come."] = "Ihr habt jeden Vertrag erfüllt, den der Geist Euch in diesem Durchlauf anbietet. Steigt eine Stufe auf, dann kommen neue.",
    -- addon:journal.you_gained_a_new_echo:text
    ["You gained a new echo! Open your Echo Journal to see it."] = "Ihr habt ein neues Echo erhalten! Öffnet Euer Echo-Journal, um es anzusehen.",
    -- addon:journal.you_gained_an_orb_of:text
    ["You gained an |cffffd700Orb of Lost Memories|r! Open your Echo Journal to spend it."] = "Ihr habt eine |cffffd700Kugel der verlorenen Erinnerungen|r erhalten! Öffnet Euer Echo-Journal, um sie einzusetzen.",
    -- addon:journal.alert_orbs_n:text
    ["You gained |cffffd700{count} Orbs of Lost Memories|r! Open your Echo Journal to spend them."] = "Ihr habt |cffffd700{count}× Kugel der verlorenen Erinnerungen|r erhalten! Öffnet Euer Echo-Journal, um sie auszugeben.",
    -- addon:collections.gs_collection_unopened_singular:text
    ["You have an unopened item in your collection."] = "Ihr habt einen ungeöffneten Gegenstand in Eurer Sammlung.",
    -- addon:collections.gs_spell_failed_mount_collected_on_other_char:text
    ["You have collected this mount but it is not usable on this character."] = "Ihr habt dieses Reittier gesammelt, aber es kann von diesem Charakter nicht benutzt werden.",
    -- addon:callboard.you_have_completed_that_contract:text
    ["You have completed that contract as many times as allowed for now."] = "Ihr habt diesen Vertrag vorerst so oft abgeschlossen, wie erlaubt ist.",
    -- addon:prestige.you_have_enough_soul_ashes:text
    ["You have enough Soul Ashes to Prestige! Open the Prestige tab to claim it."] = "Ihr habt genug Seelenasche für ein Prestige! Öffnet den Reiter „Prestige“, um es einzufordern.",
    -- addon:perks.orb_tip_no_orb:text
    ["You have no Orb to spend."] = "Ihr habt keine Kugel zum Ausgeben.",
    -- addon:journal.you_have_no_echoes_yet:text
    ["You have no echoes yet.\n\nLevel up during a run to earn new echoes."] = "Ihr habt noch keine Echos.\n\nSteigt während eines Durchlaufs eine Stufe auf, um neue Echos zu erhalten.",
    -- addon:core.you_have_no_raid_boss_looted_this_week_t:text
    ["You have no raid boss looted this week: there is nothing to renew."] = "Ihr habt diese Woche keinen Schlachtzugsboss geplündert: Es gibt nichts zu erneuern.",
    -- addon:collections.gs_err_mount_no_favorites:text
    ["You have no valid favorite mounts."] = "Ihr habt keine gültigen Lieblingsreittiere.",
    -- addon:collections.gs_mount_journal_not_collected:text
    ["You have not collected this mount."] = "Ihr habt dieses Reittier noch nicht gesammelt.",
    -- addon:extraction.book_empty_learned:text
    ["You have not learned any affix of this kind yet."] = "Ihr habt noch kein Affix dieser Art erlernt.",
    -- addon:raidLockout.you_have_not_looted_any:text
    ["You have not looted any raid boss this week."] = "Ihr habt diese Woche noch keinen Schlachtzugsboss geplündert.",
    -- addon:prestige.you_have_not_reached_the:text
    ["You have not reached the final Soul Ashes milestone."] = "Ihr habt den letzten Seelenasche-Meilenstein noch nicht erreicht.",
    -- addon:levelup.you_have_reached:text
    ["You have reached:"] = "Ihr habt erreicht:",
    -- addon:collections.gs_mount_journal_no_valid_favorites:text
    ["You have selected no favorite mounts appropriate for this area.\nRight-Click in the Mount Journal to set Favorites."] = "Ihr habt keine Lieblingsreittiere ausgewählt, die in diesem Gebiet nutzbar sind.\nKlickt im Reittierführer mit der rechten Maustaste, um Favoriten festzulegen.",
    -- addon:perks.fail_full:text
    ["You have too many wishlists. Delete one first."] = "Ihr habt zu viele Wunschlisten. Löscht zuerst eine.",
    -- addon:collections.gs_collection_unopened_plural:text
    ["You have unopened items in your collection."] = "Ihr habt ungeöffnete Gegenstände in Eurer Sammlung.",
    -- addon:editMode.you_have_unsaved_changes_to_your_layout:text
    ["You have unsaved changes to your layout."] = "Ihr habt ungespeicherte Änderungen an Eurem Layout.",
    -- addon:skillTree.you_have_unspent_skill_points:text
    ["You have unspent Skill Points! Open your Skill Tree to empower yourself with new abilities."] = "Ihr habt unverteilte Fertigkeitspunkte! Öffnet Euren Aschebaum, um Euch mit neuen Fähigkeiten zu stärken.",
    -- addon:shop.dp_balance:text
    ["You have {amount} DP(s)"] = "Ihr habt {amount} DP",
    -- addon:talents.you_have_unspent_talent_point:text
    ["You have {points} unspent talent point{s}! Open your Talents to spend {them}."] = "Noch {points} Talentpunkt{s||e} zu verteilen! Öffnet Eure Talente, um {them|ihn|sie} zu verteilen.",
    -- addon:collections.gs_transmogrify_tooltip_appearance_unknown:text
    ["You haven't collected this appearance"] = "Ihr habt diese Vorlage nicht gesammelt",
    -- addon:collections.gs_transmogrify_style_uncollected:text
    ["You haven't collected this appearance yet."] = "Ihr habt diese Vorlage noch nicht gesammelt.",
    -- addon:extraction.dd_no_affix:text
    ["You know no affix for this slot yet"] = "Ihr kennt noch kein Affix für diesen Platz",
    -- addon:collections.gs_transmog_set_partially_known:text
    ["You know some of the appearances granted by this set already."] = "Ihr kennt bereits einige der Vorlagen dieses Sets.",
    -- addon:callboard.you_must_stand_next_to:text
    ["You must stand next to the Call Board."] = "Ihr müsst neben dem Brett des Heldenrufs stehen.",
    -- addon:core.you_need_an_elixir_of_renewal:text
    ["You need an Elixir of Renewal."] = "Ihr benötigt ein Elixier der Erneuerung.",
    -- addon:core.you_need_cost_orbs_of_lost_memories:text
    ["You need {cost} Orbs of Lost Memories."] = "Du brauchst {cost} Kugeln der verlorenen Erinnerungen.",
    -- addon:perks.orb_err_only_have:text
    ["You only have {count} Orb(s) of Lost Memories."] = "Ihr habt nur {count} Kugel(n) der verlorenen Erinnerungen.",
    -- addon:trials.you_play_a:text
    ["You play a {myClass}"] = "Ihr spielt {myClass}",
    -- addon:data.mountdesc.64659:text
    ["You raised this thing from a scaly pup - Mor'vek would be so proud. But he'd still make you clean up the mess it made in the corner."] = "Ihr habt dieses Ding von einem schuppigen Welpen an großgezogen – Mor'vek wäre so stolz. Aber er würde Euch trotzdem die Sauerei in der Ecke wegmachen lassen.",
    -- addon:affixToast.you_receive:text
    ["You receive"] = "Ihr erhaltet",
    -- addon:data.mountdesc.59570:text
    ["You should never listen to minstrels' fancies. A dragon would never hurt a soul, unless they tried to hurt him first."] = "Ihr solltet niemals auf die Hirngespinste von Minnesängern hören. Ein Drache würde keiner Seele etwas zuleide tun, es sei denn, man versucht zuerst, ihm Schaden zuzufügen.",
    -- addon:skillTree.you_tried_to_import_a:text
    ["You tried to import a build without enough Soul Ashes (Required: {totalPointsRequired}, Available: {TALENTPOINTSTOTAL})"] = "Ihr habt versucht, eine Konfiguration ohne genug Seelenasche zu importieren (Benötigt: {totalPointsRequired}, Verfügbar: {TALENTPOINTSTOTAL})",
    -- addon:journal.you_unlocked_a_new_tome:text
    ["You unlocked a new Tome Echo! Open your Echo Journal to see it."] = "Ihr habt ein neues Folianten-Echo freigeschaltet! Öffnet Euer Echo-Journal, um es anzusehen.",
    -- addon:journal.alert_tome_named:text
    ["You unlocked a new Tome Echo: |cffffd700{name}|r! Open your Echo Journal to see it."] = "Ihr habt ein neues Folianten-Echo freigeschaltet: |cffffd700{name}|r! Öffnet Euer Echo-Journal, um es anzusehen.",
    -- addon:data.mountdesc.35028:text
    ["You watch what happens when their master is attacked and you will see those birds in a whole new light. - Raider Bork"] = "Seht Euch an, was passiert, wenn ihr Herr angegriffen wird, und Ihr werdet diese Vögel in einem ganz neuen Licht sehen. - Räuber Bork",
    -- addon:death.accept_confirm
    ["You will gain {gains} that you can spend in the Skill Tree.\n\nYour equipped gear will be sent to your inventory, and you will be reset to level 1 and teleported to your starting zone.\n\nAre you sure?"] = "Ihr erhaltet {gains}, die Ihr im Aschebaum ausgeben könnt.\n\nEure angelegte Ausrüstung wird in Euer Inventar gelegt, Ihr werdet auf Stufe 1 zurückgesetzt und in Euer Startgebiet teleportiert.\n\nSeid Ihr sicher?",
    -- addon:core.you_will_gain_soul_ashes:text
    ["You will gain {soulPointsGain} Soul Ashes and {soulShardsGain} Soul Shards."] = "Ihr erhaltet {soulPointsGain} Seelenasche und {soulShardsGain} Seelensplitter.",
    -- addon:core.you_will_gain_soul_ashes_2:text
    ["You will gain {soulPointsGain} Soul Ashes."] = "Ihr erhaltet {soulPointsGain} Seelenasche.",
    -- addon:callboard.you_will_start_in_cffffd100_zone_r_sub_y:text
    ["You will start in |cffffd100{zone}|r, {sub}. Your hearthstone will be bound there."] = "Ihr beginnt in |cffffd100{zone}|r, {sub}. Euer Ruhestein wird dort gebunden.",
    -- addon:data.petdesc.59250:text
    ["You wouldn't want to meet this rat in a dark alley. Or anywhere else, for that matter."] = "Dieser Ratte wollt Ihr nicht in einer dunklen Gasse begegnen. Und auch sonst nirgendwo.",
    -- addon:trials.you_top:text
    ["You |cffffffff#{myRank}|r/{total} · top |cffffffff{total2}%|r"] = "Ihr |cffffffff#{myRank}|r/{total} · Top |cffffffff{total2}%|r",
    -- addon:collections.gs_transmogrify_tooltip_appearance_known:text
    ["You've collected this appearance"] = "Ihr habt diese Vorlage gesammelt",
    -- addon:collections.gs_transmogrify_tooltip_item_unknown_appearance_known:text
    ["You've collected this appearance, but not from this item"] = "Ihr habt diese Vorlage gesammelt, aber nicht von diesem Gegenstand",
    -- addon:collections.gs_err_completed_transmog_set_s:text
    ["You've completed the set %s."] = "Ihr habt das Set %s vervollständigt.",
    -- addon:data.affix_text.your_beacon_of_light_target_takes_value:text
    ["Your Beacon of Light target takes @value@15%@value@ @range@[3%-15%]@range@ less damage, and Beacon of Light cleanses one harmful magic effect from it every 10 sec (Does not stack)"] = "Das Ziel Eurer Flamme des Glaubens erleidet @value@15%@value@ @range@[3%-15%]@range@ weniger Schaden, und Flamme des Glaubens entfernt alle 10 Sek. einen schädlichen Magieeffekt von ihm (Nicht stapelbar)",
    -- addon:data.affix_text.your_death_and_decay_becomes_felmyst_s_d:text
    ["Your Death and Decay becomes Felmyst's demonic vapor: it deals @value@50%@value@ @range@[10%-50%]@range@ more damage, and enemies that die in it rise as ghouls that fight for you for 10 sec (Does not stack)"] = "Euer Tod und Verfall wird zu Teufelsruchs dämonischem Dunst: Er verursacht @value@50%@value@ @range@[10%-50%]@range@ mehr Schaden, und Feinde, die darin sterben, erheben sich als Ghule und kämpfen 10 Sek. lang für Euch (Nicht stapelbar)",
    -- addon:data.affix_text.your_earth_shield_target_also_takes_valu:text
    ["Your Earth Shield target also takes @value@15%@value@ @range@[3%-15%]@range@ less magic damage (Does not stack)"] = "Das Ziel Eures Erdschilds erleidet zudem @value@15%@value@ @range@[3%-15%]@range@ weniger Magieschaden (Nicht stapelbar)",
    -- addon:data.affix_text.your_earthbind_totem_roots_the_first_ene:text
    ["Your Earthbind Totem roots the first enemies it slows for 2 sec, up to @value@6@value@ @range@[2-6]@range@ enemies, once every 15 sec (Does not stack)"] = "Euer Totem der Erdbindung macht die ersten Feinde, die es verlangsamt, 2 Sek. lang bewegungsunfähig, bis zu @value@6@value@ @range@[2-6]@range@ Feinde, höchstens einmal alle 15 Sek. (Nicht stapelbar)",
    -- addon:journal.your_echoes:text
    ["Your Echoes"] = "Eure Echos",
    -- addon:data.affix_text.your_fire_damage_may_hurl_a_fiery_ball_d:text
    ["Your Fire damage may hurl a fiery ball dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Fire damage, plus the same amount over 8 sec (Does not stack)"] = "Euer Feuerschaden kann eine Feuerkugel schleudern, die Feuerschaden in Höhe von @value@100%@value@ @range@[20%-100%]@range@ Eurer Zaubermacht oder Angriffskraft verursacht, plus denselben Betrag über 8 Sek. (Nicht stapelbar)",
    -- addon:data.affix_text.your_frost_damage_may_launch_a_bolt_of_f:text
    ["Your Frost damage may launch a bolt of frost dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Frost damage and slowing the target by 30% for 5 sec, increased by 20% per slowing effect on the target (Does not stack)"] = "Euer Frostschaden kann ein Frostgeschoss abfeuern, das Frostschaden in Höhe von @value@100%@value@ @range@[20%-100%]@range@ Eurer Zaubermacht oder Angriffskraft verursacht und das Ziel 5 Sek. lang um 30% verlangsamt, erhöht um 20% pro verlangsamendem Effekt auf dem Ziel (Nicht stapelbar)",
    -- addon:data.affix_text.your_immolate_leaves_a_trail_of_doomfire:text
    ["Your Immolate leaves a trail of Doomfire behind the target as it moves: enemies in it burn for @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power every second (Does not stack)"] = "Euer Feuerbrand hinterlässt hinter dem Ziel eine Spur aus Verdammnisfeuer, wenn es sich bewegt: Feinde darin brennen und erleiden jede Sekunde Schaden in Höhe von @value@50%@value@ @range@[10%-50%]@range@ Eurer Zaubermacht (Nicht stapelbar)",
    -- addon:data.affix_text.your_nature_damage_may_coat_the_target_i:text
    ["Your Nature damage may coat the target in Corrosive Acid dealing @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Nature damage every 3 sec for 15 sec and reducing its armor by 10% per periodic effect you have on it (up to 30%) (Does not stack)"] = "Euer Naturschaden kann das Ziel mit Ätzender Säure überziehen, die 15 Sek. lang alle 3 Sek. @value@67%@value@ @range@[13%-67%]@range@ Eurer Zaubermacht oder Angriffskraft als Naturschaden verursacht und seine Rüstung pro periodischem Effekt von Euch auf ihm um 10% verringert (bis zu 30%) (Nicht stapelbar)",
    -- addon:raidFinder.your_raid_finder_raid_n_total_players:text
    ["Your Raid Finder raid: {n} / {total} players."] = "Euer Schlachtzug im Schlachtzugsbrowser: {n} / {total} Spieler.",
    -- addon:raidFinder.your_raid_is_ready:text
    ["Your Raid Is Ready"] = "Euer Schlachtzug ist bereit",
    -- addon:data.affix_text.your_shadow_damage_may_send_a_shadowy_bo:text
    ["Your Shadow damage may send a shadowy bolt dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Shadow damage, increased by 20% per Shadow periodic effect you have on the target (Does not stack)"] = "Euer Schattenschaden kann ein Schattengeschoss aussenden, das Schattenschaden in Höhe von @value@100%@value@ @range@[20%-100%]@range@ Eurer Zaubermacht oder Angriffskraft verursacht, erhöht um 20% pro periodischem Schatteneffekt von Euch auf dem Ziel (Nicht stapelbar)",
    -- addon:skillTree.your_skill_tree:text
    ["Your Skill Tree"] = "Euer Aschebaum",
    -- addon:prestige.your_skill_tree_is_reset:text
    ["Your Skill Tree is reset, and every Soul Ash on the account is destroyed: the ones you banked and the ones already spent, on every character. The Ashes buy nothing back. Only |cff00FF00Carry over Prestige|r nodes survive the reset, and they become free for good. Every |cff00FF00Endless|r node is one of them: all its ranks stay."] = "Euer Aschebaum wird zurückgesetzt, und jede Seelenasche des Kontos wird vernichtet: die eingezahlte und die bereits ausgegebene, auf jedem Charakter. Die Asche kauft nichts zurück. Nur Knoten mit |cff00FF00Prestige übertragen|r überstehen das Zurücksetzen und werden dauerhaft kostenlos. Jeder |cff00FF00Endlos|r-Knoten gehört dazu: Alle seine Ränge bleiben erhalten.",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_20:text
    ["Your Spirit Wolves heal you for @value@20%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Eure Geisterwölfe heilen Euch um @value@20%@value@ @range@[20%-60%]@range@ des Schadens, den sie verursachen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_30:text
    ["Your Spirit Wolves heal you for @value@30%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Eure Geisterwölfe heilen Euch um @value@30%@value@ @range@[20%-60%]@range@ des Schadens, den sie verursachen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_40:text
    ["Your Spirit Wolves heal you for @value@40%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Eure Geisterwölfe heilen Euch um @value@40%@value@ @range@[20%-60%]@range@ des Schadens, den sie verursachen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_50:text
    ["Your Spirit Wolves heal you for @value@50%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Eure Geisterwölfe heilen Euch um @value@50%@value@ @range@[20%-60%]@range@ des Schadens, den sie verursachen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_60:text
    ["Your Spirit Wolves heal you for @value@60%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Eure Geisterwölfe heilen Euch um @value@60%@value@ @range@[20%-60%]@range@ des Schadens, den sie verursachen (Nicht stapelbar)",
    -- addon:playerRun.your_torment:text
    ["Your Torment: {tier}"] = "Eure Qual: {tier}",
    -- addon:toolbelt.chat_not_discovered:text
    ["Your account has not discovered that waystone."] = "Euer Account hat diesen Wegstein noch nicht entdeckt.",
    -- addon:itemPurchase.your_attacks_have_a_chance:text
    ["Your attacks have a chance to infect the target, dealing Shadow damage every 3 sec for 15 sec. If the target dies before the effect expires, the infection spreads to a nearby enemy, retaining its remaining duration."] = "Eure Angriffe haben eine Chance, das Ziel zu infizieren und 15 Sek. lang alle 3 Sek. Schattenschaden zu verursachen. Stirbt das Ziel, bevor der Effekt abläuft, springt die Infektion mit ihrer verbleibenden Dauer auf einen nahen Feind über.",
    -- addon:prestige.your_banked_soul_shards_are:text
    ["Your banked Soul Shards are consumed with the Ashes and come back as |cffFFCC00Soul Essence|r, one for every 750 Shards. This card shows the exchange you would make right now.\n\nSoul Essence buys the Prestige branch of the Skill Tree, and it is the only currency a prestige never takes back: it only ever grows."] = "Eure eingezahlten Seelensplitter werden mit der Asche verbraucht und kehren als |cffFFCC00Seelenessenz|r zurück, eine für je 750 Splitter. Diese Karte zeigt den Tausch, den Ihr jetzt machen würdet.\n\nSeelenessenz kauft den Prestige-Zweig des Aschebaums und ist die einzige Währung, die ein Prestige niemals zurücknimmt: Sie wächst nur.",
    -- addon:prestige.your_banked_soul_shards_are_consumed_wit:text
    ["Your banked Soul Shards are consumed with the Ashes and come back as |cffFFCC00Soul Essence|r: one for every 50 Shards on your first Prestige, 50 Shards more each time, up to 750. Your first Prestige mints at most 50 Soul Essence, the next 100, up to 750 on the 15th, then there is no limit. Shards above the limit stay banked. This card shows the exchange you would make right now.\n\nSoul Essence buys the Prestige branch of the Skill Tree, and it is the only currency a prestige never takes back: it only ever grows."] = "Eure eingezahlten Seelensplitter werden mit der Asche verbraucht und kehren als |cffFFCC00Seelenessenz|r zurück: eine für je 50 Splitter bei Eurem ersten Prestige, bei jedem weiteren 50 Splitter mehr, bis zu 750. Euer erstes Prestige prägt höchstens 50 Seelenessenz, das nächste 100, bis zu 750 beim 15., danach gibt es keine Obergrenze. Splitter über der Obergrenze bleiben eingezahlt. Diese Karte zeigt den Tausch, den Ihr jetzt machen würdet.\n\nSeelenessenz kauft den Prestige-Zweig des Aschebaums und ist die einzige Währung, die ein Prestige niemals zurücknimmt: Sie wächst nur.",
    -- addon:trials.your_best:text
    ["Your best: |cffffffff{myBest}|r"] = "Eure Bestleistung: |cffffffff{myBest}|r",
    -- addon:perks.tip_refused:text
    ["Your build refuses this echo"] = "Euer Build lehnt dieses Echo ab",
    -- addon:skillTree.your_changes_were_not_applied:text
    ["Your changes were not applied."] = "Eure Änderungen wurden nicht angewendet.",
    -- addon:raidFinder.your_class_cannot_take_this_role:text
    ["Your class cannot take this role."] = "Eure Klasse kann diese Rolle nicht übernehmen.",
    -- addon:skillTree.your_class_level_does_not:text
    ["Your class level does not allow another node yet."] = "Eure Klassenstufe erlaubt noch keinen weiteren Knoten.",
    -- addon:skillTree.your_class_progress_is_not:text
    ["Your class progress is not loaded yet, try again."] = "Euer Klassenfortschritt ist noch nicht geladen. Versucht es erneut.",
    -- addon:playerRun.your_contracts:text
    ["Your contracts"] = "Eure Verträge",
    -- addon:data.mountdesc.60116:text
    ["Your cries of \"For the Horde!\" will be much more menacing from atop a heavily armored bear that's barreling down on Alliance at top speed."] = "Euer Ruf „Für die Horde!“ wirkt viel bedrohlicher auf dem Rücken eines schwer gepanzerten Bären, der mit Höchstgeschwindigkeit auf die Allianz zudonnert.",
    -- addon:data.affix_text.your_critical_heals_heal_for_an_addition:text
    ["Your critical heals heal for an additional @value@50%@value@ @range@[10%-50%]@range@ (Does not stack)"] = "Eure kritischen Heilungen heilen @value@50%@value@ @range@[10%-50%]@range@ mehr (Nicht stapelbar)",
    -- addon:data.affix_text.your_critical_strikes_corrupt_the_target:text
    ["Your critical strikes corrupt the target for @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Shadow damage every 3 sec for 15 sec; your critical strikes make an existing Corruption flare for the same amount (once every 6 sec) (Does not stack)"] = "Eure kritischen Treffer verderben das Ziel und verursachen 15 Sek. lang alle 3 Sek. @value@67%@value@ @range@[13%-67%]@range@ Eurer Zaubermacht oder Angriffskraft als Schattenschaden; Eure kritischen Treffer lassen eine bestehende Verderbnis auflodern, die dabei denselben Schaden verursacht (höchstens einmal alle 6 Sek.) (Nicht stapelbar)",
    -- addon:data.affix_text.your_critical_strikes_may_send_a_shockwa:text
    ["Your critical strikes may send a shockwave dealing @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power as Physical damage to all enemies within 8 yards of the target (Does not stack)"] = "Eure kritischen Treffer können eine Schockwelle auslösen, die allen Feinden in einem Umkreis von 8 Metern um das Ziel @value@135%@value@ @range@[27%-135%]@range@ Eurer Angriffskraft oder Zaubermacht als körperlichen Schaden zufügt (Nicht stapelbar)",
    -- addon:torment.your_current_difficulty:text
    ["Your current difficulty"] = "Euer aktueller Schwierigkeitsgrad",
    -- addon:data.affix_text.your_damaging_spells_and_abilities_may_f:text
    ["Your damaging spells and abilities may fire an Infinite Star dealing Arcane damage equal to @value@x1,7@value@ @range@[x0,3-x1,7]@range@ your highest stat (Does not stack)"] = "Eure Schaden verursachenden Zauber und Fähigkeiten können einen Unendlichen Stern abfeuern, der Arkanschaden in Höhe von @value@x1,7@value@ @range@[x0,3-x1,7]@range@ Eures höchsten Attributs verursacht (Nicht stapelbar)",
    -- addon:data.affix_text.your_damaging_spells_and_abilities_may_r:text
    ["Your damaging spells and abilities may release a Frozen Pulse dealing Shadow damage equal to @value@67%@value@ @range@[13%-67%]@range@ of your Attack Power or Spell Power every second for 6 sec (Does not stack)"] = "Eure Schaden verursachenden Zauber und Fähigkeiten können einen Gefrorenen Puls freisetzen, der 6 Sek. lang jede Sekunde Schattenschaden in Höhe von @value@67%@value@ @range@[13%-67%]@range@ Eurer Angriffskraft oder Zaubermacht verursacht (Nicht stapelbar)",
    -- addon:perks.your_echo_is_here_click_this_button_to_o:text
    ["Your echo is here! Click this button to open |cffffd700Character Progression|r, your echoes are in the |cffffd700Echoes|r tab."] = "Euer Echo ist hier! Klickt auf diese Schaltfläche, um den |cffffd700Charakterfortschritt|r zu öffnen. Eure Echos findet Ihr im Reiter |cffffd700Echos|r.",
    -- addon:perks.your_echo_is_in_cffffd700character_progr:text
    ["Your echo is in |cffffd700Character Progression|r, |cffffd700Echoes|r tab. Type |cffffd700/collections|r to open it."] = "Euer Echo befindet sich im |cffffd700Charakterfortschritt|r, Reiter |cffffd700Echos|r. Gebt |cffffd700/collections|r ein, um ihn zu öffnen.",
    -- addon:perks.your_echoes_are_not_loaded_yet_try_again:text
    ["Your echoes are not loaded yet. Try again in a moment."] = "Eure Echos sind noch nicht geladen. Versucht es gleich noch einmal.",
    -- addon:journal.your_echoes_skill_tree_transmogrify:text
    ["Your echoes, skill tree, transmogrify, mounts and companions."] = "Eure Echos, Euer Aschebaum, Transmogrifikation, Reittiere und Begleiter.",
    -- addon:callboard.your_first_contract_claimed_today_gives:text
    ["Your first contract claimed today gives you one Elixir of Ashes and one Elixir of Shards."] = "Euer erster heute eingelöster Vertrag gibt Euch ein Elixier der Asche und ein Elixier der Splitter.",
    -- addon:data.affix_text.your_heals_may_grant_you_sanctified_ward:text
    ["Your heals may grant you Sanctified Ward for 15 sec, during which your heals also shield the target for @value@25%@value@ @range@[5%-25%]@range@ of the amount healed (Does not stack)"] = "Eure Heilungen können Euch 15 Sek. lang Geheiligte Schutzwehr gewähren; währenddessen schirmen Eure Heilungen das Ziel zusätzlich mit @value@25%@value@ @range@[5%-25%]@range@ der Heilmenge ab (Nicht stapelbar)",
    -- addon:extraction.your_item:text
    ["Your item"] = "Euer Gegenstand",
