    ["Your item has been delivered."] = "Euer Gegenstand wurde zugestellt.",
    -- addon:toolbelt.chat_macro_full:text
    ["Your macro list is full. Delete a macro to place this waystone on an action bar."] = "Eure Makroliste ist voll. Löscht ein Makro, um diesen Wegstein auf einer Aktionsleiste zu platzieren.",
    -- addon:prestige.your_next_milestone_reward_is:text
    ["Your next milestone reward is previewed here. Hover any milestone to preview its mount or transmog set."] = "Hier wird Eure nächste Meilensteinbelohnung angezeigt. Bewegt den Mauszeiger über einen Meilenstein, um eine Vorschau seines Reittiers oder Transmogrifikationssets zu sehen.",
    -- addon:dungeonFinder.your_next_run_is_at:text
