    ["Your party only"] = "Nur Eure Gruppe",
    -- addon:data.affix_text.your_periodic_heals_heal_for_an_addition:text
    ["Your periodic heals heal for an additional @value@25%@value@ @range@[5%-25%]@range@ (Does not stack)"] = "Eure periodischen Heilungen heilen @value@25%@value@ @range@[5%-25%]@range@ mehr (Nicht stapelbar)",
    -- addon:data.affix_text.your_pets_deal_value_10_value_range_10_5:text
    ["Your pets deal @value@10%@value@ @range@[10%-50%]@range@ more damage and attack @value@5%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Eure Tiere verursachen @value@10%@value@ @range@[10%-50%]@range@ mehr Schaden und greifen @value@5%@value@ @range@[5%-25%]@range@ schneller an (Nicht stapelbar)",
    -- addon:data.affix_text.your_pets_deal_value_16_value_range_10_5:text
    ["Your pets deal @value@16%@value@ @range@[10%-50%]@range@ more damage and attack @value@8%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Eure Tiere verursachen @value@16%@value@ @range@[10%-50%]@range@ mehr Schaden und greifen @value@8%@value@ @range@[5%-25%]@range@ schneller an (Nicht stapelbar)",
    -- addon:data.affix_text.your_pets_deal_value_24_value_range_10_5:text
    ["Your pets deal @value@24%@value@ @range@[10%-50%]@range@ more damage and attack @value@12%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Eure Tiere verursachen @value@24%@value@ @range@[10%-50%]@range@ mehr Schaden und greifen @value@12%@value@ @range@[5%-25%]@range@ schneller an (Nicht stapelbar)",
    -- addon:data.affix_text.your_pets_deal_value_34_value_range_10_5:text
    ["Your pets deal @value@34%@value@ @range@[10%-50%]@range@ more damage and attack @value@17%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Eure Tiere verursachen @value@34%@value@ @range@[10%-50%]@range@ mehr Schaden und greifen @value@17%@value@ @range@[5%-25%]@range@ schneller an (Nicht stapelbar)",
    -- addon:data.affix_text.your_pets_deal_value_50_value_range_10_5:text
    ["Your pets deal @value@50%@value@ @range@[10%-50%]@range@ more damage and attack @value@25%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Eure Tiere verursachen @value@50%@value@ @range@[10%-50%]@range@ mehr Schaden und greifen @value@25%@value@ @range@[5%-25%]@range@ schneller an (Nicht stapelbar)",
    -- addon:contracts.your_progress_is_lost:text
    ["Your progress ({progress} / {required}) is lost. "] = "Euer Fortschritt ({progress} / {required}) geht verloren. ",
    -- addon:callboard.your_quest_log_is_full:text
    ["Your quest log is full."] = "Euer Questlog ist voll.",
    -- addon:raidFinder.your_raid_is_ready_2:text
    ["Your raid is ready!"] = "Euer Schlachtzug ist bereit!",
    -- addon:playerRun.your_run:text
    ["Your run"] = "Euer Durchlauf",
    -- addon:core.your_run_does_not_hold:text
    ["Your run does not hold enough Soul Ashes."] = "Euer Durchlauf enthält nicht genug Seelenasche.",
    -- addon:playerRun.your_run_your_collection_and:text
    ["Your run, your collection and all existing echoes"] = "Euer Durchlauf, Eure Sammlung und alle vorhandenen Echos",
    -- addon:raidFinder.your_seat_role:text
    ["Your seat: {role}"] = "Euer Platz: {role}",
    -- addon:contracts.your_soul_is_anchored_to:text
    ["Your soul is anchored to this spirit. Releasing it is free."] = "Eure Seele ist an diesen Geist gebunden. Sie zu lösen ist kostenlos.",
    -- addon:contracts.your_soul_is_anchored_to_2:text
    ["Your soul is anchored to {anchorPlace}. Move it here for the run's Soul Ashes."] = "Eure Seele ist an {anchorPlace} gebunden. Versetzt sie für die Seelenasche des Durchlaufs hierher.",
    -- addon:data.affix_text.your_spells_and_abilities_have_a_chance:text
    ["Your spells and abilities have a chance to make your next spell or ability cost nothing, about @value@10@value@ @range@[4-10]@range@ times per minute (Does not stack)"] = "Eure Zauber und Fähigkeiten haben eine Chance, Euren nächsten Zauber oder Eure nächste Fähigkeit kostenlos zu machen, etwa @value@10@value@ @range@[4-10]@range@-mal pro Minute (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_wound_the:text
    ["Your spells and abilities may Wound the target for @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power; twice as likely from behind (Does not stack)"] = "Eure Zauber und Fähigkeiten können dem Ziel eine Wunde zufügen, die Schaden in Höhe von @value@135%@value@ @range@[27%-135%]@range@ Eurer Angriffskraft oder Zaubermacht verursacht; von hinten ist die Wahrscheinlichkeit doppelt so hoch (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_blast_the:text
    ["Your spells and abilities may blast the target with lightning dealing @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Nature damage, jumping to 4 more enemies and making each victim take 25% more Nature damage from you for 12 sec; the primary target is caught in a cyclone slowing its attacks by 20% for 12 sec (Does not stack)"] = "Eure Zauber und Fähigkeiten können das Ziel mit einem Blitz treffen, der @value@67%@value@ @range@[13%-67%]@range@ Eurer Zaubermacht oder Angriffskraft als Naturschaden verursacht, auf 4 weitere Feinde überspringt und jedes Opfer 12 Sek. lang 25% mehr Naturschaden von Euch erleiden lässt; das Hauptziel wird von einem Wirbelsturm erfasst, der 12 Sek. lang sein Angriffstempo um 20% verringert (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_call_forth:text
    ["Your spells and abilities may call forth an Ember Guardian for 15 sec, dealing @value@135%@value@ @range@[27%-135%]@range@ of its normal damage (once every 30 sec) (Does not stack)"] = "Eure Zauber und Fähigkeiten können 15 Sek. lang einen Glutwächter herbeirufen, der @value@135%@value@ @range@[27%-135%]@range@ seines normalen Schadens verursacht (höchstens einmal alle 30 Sek.) (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_disarm_the:text
    ["Your spells and abilities may disarm the target for @value@3 sec@value@ @range@[1 sec-3 sec]@range@ (once every 15 sec) (Does not stack)"] = "Eure Zauber und Fähigkeiten können das Ziel @value@3 sec@value@ @range@[1 sec-3 sec]@range@ lang entwaffnen (einmal alle 15 Sek.) (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_hurl_a_fie:text
    ["Your spells and abilities may hurl a fiery ball dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Fire damage plus the same amount over 10 sec, increased by 10% per Fire periodic effect you have on the target (Does not stack)"] = "Eure Zauber und Fähigkeiten können eine Feuerkugel schleudern, die Feuerschaden in Höhe von @value@100%@value@ @range@[20%-100%]@range@ Eurer Zaubermacht oder Angriffskraft verursacht, plus denselben Betrag über 10 Sek., erhöht um 10% pro periodischem Feuereffekt von Euch auf dem Ziel (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_increase_t:text
    ["Your spells and abilities may increase the target's spell damage taken by @value@5%@value@ @range@[1%-5%]@range@ for 5 sec (Does not stack)"] = "Eure Zauber und Fähigkeiten können den vom Ziel erlittenen Zauberschaden 5 Sek. lang um @value@5%@value@ @range@[1%-5%]@range@ erhöhen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_increase_y:text
    ["Your spells and abilities may increase your critical strike damage by @value@50%@value@ @range@[10%-50%]@range@ for 10 sec (Does not stack)"] = "Eure Zauber und Fähigkeiten können Euren kritischen Trefferschaden 10 Sek. lang um @value@50%@value@ @range@[10%-50%]@range@ erhöhen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_inflict_a:text
    ["Your spells and abilities may inflict a Fatal Wound dealing Physical damage equal to @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power (Does not stack)"] = "Eure Zauber und Fähigkeiten können eine Tödliche Wunde zufügen, die körperlichen Schaden in Höhe von @value@135%@value@ @range@[27%-135%]@range@ Eurer Angriffskraft oder Zaubermacht verursacht (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_poison_the:text
    ["Your spells and abilities may poison the target for @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power over 8 sec; poisoned targets take 5% more damage from your periodic effects (Does not stack)"] = "Eure Zauber und Fähigkeiten können das Ziel vergiften und über 8 Sek. Schaden in Höhe von @value@135%@value@ @range@[27%-135%]@range@ Eurer Angriffskraft oder Zaubermacht verursachen; vergiftete Ziele erleiden 5% mehr Schaden durch Eure periodischen Effekte (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_restore_va:text
    ["Your spells and abilities may restore @value@10%@value@ @range@[2%-10%]@range@ of your maximum resource (once every 6 sec) (Does not stack)"] = "Eure Zauber und Fähigkeiten können @value@10%@value@ @range@[2%-10%]@range@ Eurer maximalen Ressource wiederherstellen (höchstens einmal alle 6 Sek.) (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_smite_the:text
    ["Your spells and abilities may smite the target for @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Holy damage (Does not stack)"] = "Eure Zauber und Fähigkeiten können dem Ziel Heiligschaden in Höhe von @value@100%@value@ @range@[20%-100%]@range@ Eurer Zaubermacht oder Angriffskraft zufügen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_strike_the:text
    ["Your spells and abilities may strike the target for @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power as Frost damage (Does not stack)"] = "Eure Zauber und Fähigkeiten können das Ziel treffen und Frostschaden in Höhe von @value@135%@value@ @range@[27%-135%]@range@ Eurer Angriffskraft oder Zaubermacht verursachen (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_stun_the_t:text
    ["Your spells and abilities may stun the target for @value@3 sec@value@ @range@[1 sec-3 sec]@range@ (once every 10 sec) (Does not stack)"] = "Eure Zauber und Fähigkeiten können das Ziel @value@3 Sek.@value@ @range@[1 Sek.-3 Sek.]@range@ lang betäuben (einmal alle 10 Sek.) (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_abilities_may_summon_a_b:text
    ["Your spells and abilities may summon a Bound Spirit for 15 sec, dealing @value@135%@value@ @range@[27%-135%]@range@ of its normal damage (once every 30 sec) (Does not stack)"] = "Eure Zauber und Fähigkeiten können 15 Sek. lang einen Gebundenen Geist beschwören, der @value@135%@value@ @range@[27%-135%]@range@ seines normalen Schadens verursacht (einmal alle 30 Sek.) (Nicht stapelbar)",
    -- addon:data.affix_text.your_spells_and_attacks_reduce_the_targe:text
    ["Your spells and attacks reduce the target's armor by @value@15%@value@ @range@[3%-15%]@range@ for 10 sec (Does not stack)"] = "Eure Zauber und Angriffe verringern die Rüstung des Ziels 10 Sek. lang um @value@15%@value@ @range@[3%-15%]@range@ (Nicht stapelbar)",
