    ["|cffFF8000Legendary|r"] = "|cffFF8000Legendär|r",
    -- addon:perks.orb_dlg_claim_first:text
    ["|cffFF8080Claim your current Echo choice first to spend more.|r"] = "|cffFF8080Nehmt zuerst Eure aktuelle Echo-Auswahl an, um mehr einzusetzen.|r",
    -- addon:journal.permanent_echoes_cannot_be_forgotten:text
    ["|cffFF8080Permanent Echoes cannot be forgotten|r"] = "|cffFF8080Permanente Echos können nicht vergessen werden|r",
    -- addon:journal.you_do_not_own_this:text
    ["|cffFF8080You do not own this Echo|r"] = "|cffFF8080Ihr besitzt dieses Echo nicht|r",
    -- addon:prestige.prestige_locked_soul_ashes_committed:text
    ["|cffFF9900[Prestige] Locked: {GetGateProgress} / {GetGateThreshold} Soul Ashes committed to the Skill Tree.|r"] = "|cffFF9900[Prestige] Gesperrt: {GetGateProgress} / {GetGateThreshold} Seelenasche in den Aschebaum investiert.|r",
    -- addon:skillTree.only_one_apex_talent_can:text
    ["|cffFFAAAAOnly one Apex Talent can be active at a time.|r"] = "|cffFFAAAAEs kann immer nur ein Apex-Talent aktiv sein.|r",
    -- addon:raidLockout.raids_have_no_id_join:text
    ["|cffFFCC00Raids have no ID: join any group, any time.\nEach boss can be looted once a week.\nRaid Info lists the bosses you looted.|r"] = "|cffFFCC00Schlachtzüge haben keine ID: Tretet jederzeit jeder Gruppe bei.\nJeder Boss kann einmal pro Woche geplündert werden.\nDie Schlachtzugsinfo listet die Bosse auf, die Ihr geplündert habt.|r",
    -- addon:prestige.soul_essence_buys_the_prestige:text
    ["|cffFFCC00Soul Essence|r buys the Prestige branch, and no prestige takes it back."] = "|cffFFCC00Seelenessenz|r kauft den Prestige-Zweig, und kein Prestige nimmt sie zurück.",
    -- addon:journal.left_click_to_forget_one:text
    ["|cffFFD100Left-click to forget one stack now|r"] = "|cffFFD100Linksklick, um jetzt einen Stapel zu vergessen|r",
    -- addon:perks.orb_help:text
    ["|cffFFD100Orb of Lost Memories|r\n\n|cffFFD100Left-click|r an Echo to forget a stack, or |cffFFD100right-click|r several to forget them together, one Orb each.\n\nEach draws a new Echo choice. Your |cffFF8080reroll, freeze and banish|r do not apply to those draws; |cffFFD100another Orb|r redraws them."] = "|cffFFD100Kugel der verlorenen Erinnerungen|r\n\n|cffFFD100Linksklick|r auf ein Echo, um einen Stapel zu vergessen, oder |cffFFD100Rechtsklick|r auf mehrere, um sie gemeinsam zu vergessen, je eine Kugel pro Echo.\n\nJedes zieht eine neue Echo-Auswahl. Euer |cffFF8080Neuwurf, Einfrieren und Verbannen|r gelten nicht für diese Ziehungen; |cffFFD100eine weitere Kugel|r zieht sie neu.",
    -- addon:spellUnlearn.right_click_an_echo_to:text
    ["|cffFFD100Right-click an Echo to unlearn it|r"] = "|cffFFD100Rechtsklick auf ein Echo, um es zu verlernen|r",
    -- addon:journal.right_click_to_add_it:text
    ["|cffFFD100Right-click to add it to a batch|r"] = "|cffFFD100Rechtsklick, um es der Auswahl hinzuzufügen|r",
    -- addon:journal.right_click_to_take_it:text
    ["|cffFFD100Right-click to take it back out|r"] = "|cffFFD100Rechtsklick, um es wieder herauszunehmen|r",
    -- addon:torment.torment_unlocked:text
    ["|cffFFD100[Torment]|r {tierName} unlocked!"] = "|cffFFD100[Qual]|r {tierName} freigeschaltet!",
    -- addon:torment.unlocked:text
    ["|cffFFD100{tierName} unlocked!|r\n\n"] = "|cffFFD100{tierName} freigeschaltet!|r\n\n",
    -- addon:skillTree.kept_through_prestige_with_every:text
    ["|cffFFD700Kept through Prestige, with every rank.|r"] = "|cffFFD700Bleibt über Prestige hinweg erhalten, mit allen Rängen.|r",
    -- addon:skillTree.permanent_node_every_rank_you:text
    ["|cffFFD700Permanent node|r\n\nEvery rank you apply in the Skill Tree is |cffFF0000permanent|r: it can never be unlearned or refunded. A |cffFF4444Prestige|r is the only thing that clears the tree, and it wipes almost all of it.\n\nThe node you are about to take wears an |cffFFD700octagon|r frame: it is one of the few that SURVIVE a Prestige, keeping its ranks for free forever.\n\nChoose those points carefully!"] = "|cffFFD700Dauerhafter Knoten|r\n\nJeder Rang, den Ihr im Aschebaum übernehmt, ist |cffFF0000dauerhaft|r: Er kann nie verlernt oder erstattet werden. Nur ein |cffFF4444Prestige|r leert den Baum, und es löscht fast alles darin.\n\nDer Knoten, den Ihr gleich nehmt, trägt einen |cffFFD700achteckigen|r Rahmen: Er ist einer der wenigen, die ein Prestige ÜBERSTEHEN, und behält seine Ränge für immer kostenlos.\n\nWählt diese Punkte mit Bedacht!",
    -- addon:playerRun.right_click_to_unlock:text
    ["|cffFFD700Right-click to unlock|r"] = "|cffFFD700Rechtsklick zum Freischalten|r",
    -- addon:spec.this_will_refund_all_spent:text
    ["|cffFFD700This will refund all spent talent points, allowing you to redistribute them.|r"] = "|cffFFD700Dies erstattet alle ausgegebenen Talentpunkte, damit Ihr sie neu verteilen könnt.|r",
    -- addon:skillTree.hover_over_this_node_to:text
    ["|cffFFFF00Hover over this node to see available choices|r"] = "|cffFFFF00Fahrt mit der Maus über diesen Knoten, um die verfügbaren Optionen zu sehen|r",
    -- addon:core.project_ebonhold_no_death_recap:text
    ["|cffFFFF00Project Ebonhold:|r no death recap recorded yet."] = "|cffFFFF00Project Ebonhold:|r noch keine Todesübersicht aufgezeichnet.",
    -- addon:skillTree.refreshloadoutdropdown_dropdown_not_initialized_yet:text
    ["|cffFFFF00RefreshLoadoutDropdown: dropdown not initialized yet, will update on creation|r"] = "|cffFFFF00RefreshLoadoutDropdown: Dropdown noch nicht initialisiert, wird beim Erstellen aktualisiert|r",
    -- addon:skillTree.right_click_to_take_it:text
