    -- addon:contracts.take_this_contract:text
    ["|cffffd700Take this contract?|r\n\n{c}\n{c2}\n\n|cffffd100+{bonus}%|r{time}"] = "|cffffd700Diesen Vertrag annehmen?|r\n\n{c}\n{c2}\n\n|cffffd100+{bonus}%|r{time}",
    -- addon:contracts.the_cull_kill_50_creatures:text
    ["|cffffd700The Cull|r: kill 50 creatures in a zone. |cffffd700The Execution|r: kill every boss of a dungeon or a raid. A contract pays for the time it asks: the longer its hourglass, the bigger its bonus, and the newest raids pay best. At level 80 the spirit offers them at the highest Torment you have unlocked: a contract only counts at that Torment or higher, once per run."] = "|cffffd700Die Auslese|r: Tötet 50 Kreaturen in einem Gebiet. |cffffd700Die Hinrichtung|r: Tötet jeden Boss eines Dungeons oder Schlachtzugs. Ein Vertrag zahlt für die Zeit, die er verlangt: Je länger seine Sanduhr, desto größer sein Bonus, und die neuesten Schlachtzüge zahlen am besten. Auf Stufe 80 bietet der Geist sie auf der höchsten Qual an, die Ihr freigeschaltet habt: Ein Vertrag zählt nur auf dieser Qual oder höher, einmal pro Durchlauf.",
    -- addon:journal.d_echo_es_d_d:text
    ["|cffffffff%d|r echo(es), |cffffffff%d/%d|r stacks"] = "|cffffffff%d|r Echo(s), |cffffffff%d/%d|r Stapel",
