    -- addon:prestige.soul_essence:text
    ["|r Soul Essence"] = "|r Seelenessenz",
    -- addon:prestige.all_soul_ashes_banked_or:text
    ["• ALL Soul Ashes, banked or spent,\n   on EVERY character\n• ALL banked Soul Shards\n   (turned into Soul Essence, 750 to 1)\n• Skill Tree nodes without\n   Carry over Prestige"] = "• ALLE Seelenasche, eingezahlt oder ausgegeben,\n   auf JEDEM Charakter\n• ALLE eingezahlten Seelensplitter\n   (umgewandelt in Seelenessenz, 750 zu 1)\n• Knoten des Aschebaums ohne\n   „Prestige übertragen“",
    -- addon:prestige.all_soul_ashes_banked_or_spent_on_every:text
    ["• ALL Soul Ashes, banked or spent,\n   on EVERY character\n• Your banked Soul Shards\n   (turned into Soul Essence)\n• Skill Tree nodes without\n   Carry over Prestige"] = "• ALLE Seelenasche, eingezahlt oder ausgegeben,\n   auf JEDEM Charakter\n• Eure eingezahlten Seelensplitter\n   (umgewandelt in Seelenessenz)\n• Knoten des Aschebaums ohne\n   „Prestige übertragen“",
    -- addon:prestige.your_level_and_your_current:text
